insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('watkins-glen-new-york', '12A', 'Watkins Glen State Park', 'United States', 'Nineteen waterfalls above Seneca Lake wine country', 'future', 'verified', 'mountainValley', 'New York State & the Hudson', '{"hiking","wine","family","spectator","glamping","sailing","parks"}', '{"dramatic","pastoral","family-friendly"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"The Gorge Trail","source":"https://parks.ny.gov/visit/state-parks/watkins-glen-state-park","accessed":"2026-10-03","si":["hiking","family","adventure","senior"],"booking_route":"none needed - $10 per vehicle entrance fee at the park","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"fit_rules":{"duration":"about 1.5 to 2 hours one way, depending on stops (explorewatkinsglen.com)","before":"the trail has stone steps, \"a difficult hike for some visitors\" (parks.ny.gov)","after":"return by the South Rim Trail or the $6 park shuttle","pairs_with":"the South Rim Trail loop; the park pool in summer","pace":"moderately-active","time_season":"mid to late May to October 25, 2026; arrive early to avoid crowds"},"blurb":"NY State Parks: \"The Gorge Trail with 19 waterfalls in a 1-mile stretch\"; within two miles the glen descends 400 feet past 200-foot cliffs. It \"will close for the season on October 25, 2026\" and \"re-open for the season in mid to late May\"; \"Pets are not allowed on the Gorge Trail.\""},{"name":"Watkins Glen International","source":"https://speedwaydigest.com/?p=569291","accessed":"2026-10-03","si":["spectator","motoring","sports","group"],"booking_route":"own website ticketing at theglen.com (as the release states; theglen.com returned 403 to this build)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":2,"blurb":"A 2.45-mile road course in the Finger Lakes. Its 2026 NASCAR weekend: \"Friday, May 8 - NASCAR CRAFTSMAN Truck Series Race\", \"Saturday, May 9 - NASCAR O''Reilly Auto Parts Series Mission 200 at The Glen\", \"Sunday, May 10 - NASCAR Cup Series Go Bowling at The Glen\". \"Fans can purchase tickets... at www.theglen.com.\""},{"name":"North and South Rim Trails","source":"https://parks.ny.gov/visit/state-parks/watkins-glen-state-park","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"none needed - park entrance fee only","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"NY State Parks: the North and South Rim trails are open year-round, sunrise to sunset, with no gorge or waterfall access November to May. Pets are allowed in day use areas \"(except the Gorge Trail)\", a maximum of two, on a leash no longer than 6 feet."},{"name":"Captain Bill''s Seneca Lake Cruises","source":"https://www.senecaharborstation.com/","accessed":"2026-10-03","si":["ocean","family","senior","culinary","romance","group"],"booking_route":"FareHarbor (fareharbor.com/embeds/book/senecaharborstation) or 607-535-4541","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","eat"],"draw_rank":4,"blurb":"From Seneca Harbor Station, 1 N. Franklin St: the Seneca Spirit''s \"50-minute narrated excursion\" past Hector Falls and the east shore cliffs and a \"1.5-hour twilight journey\"; the Seneca Legacy''s dinner cruises with a \"multi-course meal featuring the best of the Finger Lakes\", music evenings and lunch cruises; \"From spring through fall\"; charters for \"up to 200 dining guests or 250 passengers\"."},{"name":"Watkins Glen Harbor Hotel","source":"https://www.watkinsglenharborhotel.com/","accessed":"2026-10-03","si":["romance","wine","culinary","senior","spectator"],"booking_route":"own website booking (reservations.watkinsglenharborhotel.com) or (607) 535-6116","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","eat"],"draw_rank":5,"blurb":"\"A premier four-season resort\" \"at the southern tip of Seneca Lake\", with lake-view deluxe rooms and suites, many with private balconies; Blue Pointe Grille and Coldwater Bar; the park offers \"unforgettable outdoor experiences just moments from the hotel\" in the hotel''s words."},{"name":"Glenora Wine Cellars and the Inn at Glenora","source":"https://www.glenora.com/","accessed":"2026-10-03","si":["wine","romance","culinary","senior"],"booking_route":"own website booking or 800-243-5513","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","eat","shop"],"draw_rank":6,"blurb":"\"The first winery on Seneca Lake, located just 10 minutes from Watkins Glen\", \"Since 1977\"; a 30-room Inn, Veraisons Restaurant with a covered terrace, daily tastings and \"behind-the-scenes cellar tours\". An October offer read today: Sunday-Thursday stays from $153.30 per night with code FALL."},{"name":"Hermann J. Wiemer Vineyard","source":"https://www.wiemer.com/","accessed":"2026-10-03","si":["wine","culinary"],"booking_route":"Tock (exploretock.com/wiemer) or walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities","shop"],"draw_rank":7,"blurb":"Founded 1979 at 3962 NY-14, Dundee; \"one of the region''s indisputable flagships\", quoting Wine & Spirits: \"When it comes to Riesling, there is simply no one better in the United States.\" Reserved educational tastings on Tock or walk-ins for wines by the glass; guided Harvest Tours October 9 and 16, 2026, 3:00-4:15 pm."},{"name":"Watkins Glen State Park Campground and Rustic Cabins","source":"https://parks.ny.gov/parks/watkinsglen/details.aspx","accessed":"2026-10-03","si":["family","hiking","overland"],"booking_route":"ReserveAmerica online or 1-800-456-2267","commission_status":"none","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":8,"blurb":"Tent and trailer sites $18-$30 per night; rustic cabins $58 per night with a 3-night minimum; an out-of-state camping fee is added. The 2026 season opened May 8; reservations through ReserveAmerica or 1-800-456-2267."},{"name":"Free Gorge Tours with the Finger Lakes Environmental Education Department","source":"https://parks.ny.gov/visit/state-parks/watkins-glen-state-park","accessed":"2026-10-03","si":["hiking","family","senior","culture"],"booking_route":"none needed for individuals; groups of 10+ by the park''s form or email","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"\"Free and open to the public\" with no registration (parking fees may apply), about 1.5 hours: \"You''ll tour a mile of the gorge trail that follows Glen Creek past water-sculpted rocks, through tunnels, next to and actually under two waterfalls.\" Groups of 10+ use the park''s form or email the regional educators."},{"name":"Schooner True Love","source":"https://sailtruelove.com/","accessed":"2026-10-03","si":["sailing","romance","group","ocean"],"booking_route":"FareHarbor online booking or 607-535-LAKE (5253)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":10,"blurb":"Seneca Sailing Adventures sails the schooner True Love, built 1926 (christened \"Venona II\" by Pendleton Brothers Shipyard, Wiscasset, Maine), from Seneca Harbor Park Pier in Watkins Glen: public day sails, private charters, engagements and weddings, and corporate trips; the site marks a 100-year celebration in September 2026."},{"name":"Seneca Lodge","source":"https://www.senecalodge.com/","accessed":"2026-10-03","si":["hiking","family","culinary","senior"],"booking_route":"phone/email only (607-535-2014, senecalodge@gmail.com)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","eat"],"draw_rank":11,"blurb":"\"Simple - Rustic - Charming\", operating since 1948, \"a stone''s throw from the gorge in Watkins Glen State Park\" at 3600 St Rt 419; \"more than 80 units\" from cabins and A-frames to motel rooms; dinner \"7 Days a week, Starting by 5pm\" with a full bar."},{"name":"Montour Falls, the Valley of Tumbling Waters","source":"https://www.villageofmontourfalls.com/","accessed":"2026-10-03","si":["hiking","culture","senior"],"booking_route":"none needed - a public village","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":12,"blurb":"The neighbouring village: \"As the southern gateway to the Finger Lakes Region Montour Falls is noted for its natural as well as its historical beauty. Surrounded by hills rising 1,000 feet, it is the focal point for seven natural glens which radiate from its borders, with more than a score of beautiful waterfalls\"."},{"name":"Naturluxe & Stars","source":"https://www.naturluxeandstars.com/","accessed":"2026-10-03","si":["glamping","romance","hiking","spectator"],"booking_route":"own website booking (naturluxeandstars.com/book-online) or (607) 944-0304","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":13,"blurb":"\"Luxury outdoor resorts exquisitely, impeccably designed for those who revere both luxury and the outdoors\" at 2870 County Road 16, Watkins Glen; featured in \"USA Today''s Top Ten Glamping Spots\" (2023 & 2025), on its own site."},{"name":"Taughannock Falls State Park","source":"https://parks.ny.gov/visit/state-parks/taughannock-falls-state-park","accessed":"2026-10-03","si":["hiking","family","senior"],"booking_route":"none needed for day use - $10 vehicle fee; camping on ReserveAmerica","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":14,"blurb":"In the ring on Cayuga Lake: \"Taughannock Falls plunges 215 feet past rocky cliffs that tower nearly 400 feet above the gorge\"; gorge and rim trails, the gorge trail about three-quarters of a mile and relatively flat; $10 vehicle entry; camping May 15 - October 12, 2026; swimming June 26 through Labor Day."},{"name":"The Park''s Olympic-size Pool","source":"https://parks.ny.gov/visit/state-parks/watkins-glen-state-park","accessed":"2026-10-03","si":["family"],"booking_route":"none needed - included in the vehicle entrance fee","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":15,"blurb":"2026 season June 27 to September 7; weekdays 12:00 pm to 5:45 pm, weekends 11:30 am to 6:45 pm; \"Dates and times are subject to change\". Entry is included in the $10 vehicle fee."},{"name":"Seneca Harbor Station","source":"https://www.senecaharborstation.com/","accessed":"2026-10-03","si":["culinary","wine","family"],"booking_route":"phone/email only (607-535-6101)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":16,"blurb":"Restaurant at the harbour, North Franklin Street, with roots in 1963 and lake sightseeing back to 1908 - \"a living piece of local history\" run by one family across generations; \"seasonal menus\" with \"dishes inspired by what''s fresh and local\" and Finger Lakes wines."},{"name":"Fox Run Vineyards","source":"https://www.foxrunvineyards.com/","accessed":"2026-10-03","si":["wine","culinary"],"booking_route":"walk-in; tour tickets bought in the tasting room","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities","eat","shop"],"draw_rank":17,"blurb":"670 State Route 14, Penn Yan, on Seneca Lake, 36 years of cool-climate wine: \"No velvet ropes, no stuffy tastings, no exclusivity contests...just great wine.\" Tasting room Mon-Sat 10am-6pm, Sun 11am-6pm; vineyard tours every hour on the hour until 4pm, year-round, tickets in the tasting room; Fox Run Cafe daily 11am-5pm; the Vineyard House for overnight stays."},{"name":"Atwater Vineyards","source":"https://www.atwatervineyards.com/","accessed":"2026-10-03","si":["wine"],"booking_route":"Tock (exploretock.com) or walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities","shop"],"draw_rank":18,"blurb":"On Seneca Lake''s eastern slopes: \"expressive, small-batch wines from our estate\" made with \"a low-intervention approach\", NY Sustainable Winegrowing certified; tasting room daily 11:00 AM-6:00 PM plus the outdoor Vista Bar; reservations encouraged for weekends and groups of six or more."},{"name":"Two Goats Brewing","source":"https://www.twogoatsbrewing.com/","accessed":"2026-10-03","si":["culinary","entertainment"],"booking_route":"none - walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":19,"blurb":"A brewpub overlooking Seneca Lake at 5027 State Route 414, Burdett: \"Good beer. Good beef. Good people.\" Beef-on-Weck, flights and growlers, FLX wine and cider; open year-round, live music Thursday to Sunday in season; the building runs \"75% by solar\"."},{"name":"Stonecat Cafe","source":"https://www.stonecatcafe.com/","accessed":"2026-10-03","si":["culinary","wine"],"booking_route":"none - first come, first served","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":20,"blurb":"\"Serving Regional Organic Cuisine with a smile since 1999\" at 5315 State Route 414, Hector; 80% sourced locally, whole-animal butchery; seasonal \"early April through mid-November\", closing November 8, 2026; \"Seating available on a first come, first serve basis.\""},{"name":"Nickel''s Pit BBQ","source":"https://www.nickelspitbbq.com/","accessed":"2026-10-03","si":["culinary","family","spectator"],"booking_route":"none - first come, first served; (607) 210-4646","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":21,"blurb":"\"The Finger Lakes'' premier BBQ destination since 2012\" at 207 N Franklin St; fall 2026 hours Mon-Wed 4-9pm, Thu-Fri 4-10pm, Sat 12-10pm, Sun 12-9pm; \"We do not accept reservations at either location for any size party.\""},{"name":"Lakeside Resort and 3812 Bistro","source":"https://www.lakeside-resort.com/","accessed":"2026-10-03","si":["family","culinary","wine"],"booking_route":"own website booking (Cloudbeds) or (607) 535-4232","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","eat"],"draw_rank":22,"blurb":"A pet-friendly hotel on Seneca Lake at 3812 New York Highway 14: \"Lake views, walking trails, waterfalls, campfires, pet friendly\"; lake-view cabins with full kitchens looking to Hector Falls, balcony rooms, creekside and garden cabins; 3812 Bistro serves \"breakfast, lunch, dinner, beer & wine every day\"; 2 pets per room at $50 per stay."},{"name":"The Hotel Laurel at Seneca","source":"https://www.thehotellaurel.com/","accessed":"2026-10-03","si":["romance","wine","culinary"],"booking_route":"own website booking or (607) 535-2706","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","eat"],"draw_rank":23,"blurb":"At 3380 NY-14, \"nestled above the tranquil waters of Seneca Lake\" with \"every guest room thoughtfully positioned to face the lake\"; two-bed rooms and king suites, select rooms with balcony; the Grill at Laurel with \"local wines, craft brews, and relaxed evenings on-site.\""},{"name":"The Park Shuttle Between the Three Entrances","source":"https://parks.ny.gov/parks/watkinsglen/details.aspx","accessed":"2026-10-03","si":["hiking","family","senior"],"booking_route":"pay at the park - $6 per person one way","commission_status":"none","commission":"operator","tier_absent_reason":"does-not-compete","wells":["move"],"draw_rank":24,"blurb":"\"Shuttle, when in operation runs between all 3 entrances\" - Main (1009 N. Franklin St), South (3530 Route 419) and Upper (3310 Route 409); $6 per person one way; weekends May 23 to June 27, daily June 28 to September 7, weekends September 8 to the end of season (mid-October 2026)."},{"name":"Grist Iron Brewing Company and the Lodge","source":"https://www.gristironbrewing.com/","accessed":"2026-10-03","si":["culinary","group"],"booking_route":"own reservation system; brewery (607) 882-2739, lodge (607) 546-4066","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["eat","stay"],"draw_rank":25,"blurb":"\"Hand-crafting exceptional craft beer and unforgettable experiences in the Finger Lakes since 2015\" at 4880 NY-414, Burdett; \"house-made pizzas and elevated pub favorites\"; guest rooms at The Lodge at Grist Iron Brewing and The Farmhouse."},{"name":"Cool Lea Campground","source":"https://www.coolleacamp.com/","accessed":"2026-10-03","si":["family","overland"],"booking_route":"Campspot (linked from its site) or 607-220-7531","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"not-established","commission_pct_low":3,"commission_pct_high":3,"commission_basis":"published","wells":["stay"],"draw_rank":26,"blurb":"\"A family oriented privately owned and operated campground\" on Cayuta Lake in Odessa, \"just minutes away from Ithaca, Watkins Glen and Montour falls\"; full hook-up, water and electric and primitive tent sites, cottages, cabins and rental campers; free boat launch for campers, canoe and kayak rentals, live Saturday entertainment."},{"name":"Jerlando''s Ristorante & Pizza Co","source":"https://www.jerlandospizza.com/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"own website online ordering; walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":27,"blurb":"\"Established in 1993, Jerlando''s restaurant is in the heart of the Finger Lakes in Watkins Glen, NY\", Italian and American cuisine, dine-in, takeout, online ordering and catering."},{"name":"Hector Hideaway","source":"https://www.hectorhideaway.com/","accessed":"2026-10-03","si":["culinary","wine"],"booking_route":"phone/email only ((607) 210-2677)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":28,"blurb":"\"A Restaurant and Bar located in the heart of the Seneca Lake Wine Trail\" at 3708 Mathews Road, Burdett, on the Vineyard Villas property; \"a full-service bar serving up craft cocktails and local wine, beer, ciders, and spirits\", sourced only from New York State."},{"name":"Catharine Creek and Seneca Lake Fishing","source":"https://parks.ny.gov/visit/state-parks/watkins-glen-state-park","accessed":"2026-10-03","si":["wildlife","adventure"],"booking_route":"none needed - public water (a New York fishing licence rule was not read in this build)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":29,"blurb":"NY State Parks: fishing \"in nearby Seneca Lake or Catharine Creek, which is renowned for its annual spring run of rainbow trout.\""},{"name":"Picnic Pavilions for Gatherings and Weddings","source":"https://parks.ny.gov/visit/state-parks/watkins-glen-state-park","accessed":"2026-10-03","si":["group","romance","family"],"booking_route":"Reserve America online","commission_status":"none","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":30,"blurb":"Two pavilions, \"$75 to $150\", capacity up to 122 people, reserved through Reserve America."},{"name":"Hillside Haven","source":"https://www.campspot.com/park/hillside-haven-trumansburg-ny","accessed":"2026-10-03","si":["overland","family","hiking","wine"],"booking_route":"Campspot online booking","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"not-established","commission_pct_low":3,"commission_pct_high":3,"commission_basis":"published","wells":["stay"],"draw_rank":31,"blurb":"At 5287 Searsburg Road, Trumansburg, in the Town of Hector, about five miles from the Seneca Wine Trail and bordering the Finger Lakes National Forest: 13 RV sites, back-in and pull-through, with \"20-Amp - 30-Amp - 50-Amp\" electric, sewer and water; 2 cabins and 3 tent sites; dump station and playground; $50-$115 nightly by site type; pets allowed. Campspot lists it 12 miles from Watkins Glen."},{"name":"Yogi Bear''s Jellystone Park Camp-Resort: Finger Lakes","source":"https://www.campspot.com/park/yogi-bear-jellystone-finger-lakes","accessed":"2026-10-03","si":["family","overland"],"booking_route":"Campspot online booking","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"not-established","commission_pct_low":3,"commission_pct_high":3,"commission_basis":"published","wells":["stay"],"draw_rank":32,"blurb":"At 5932 County Route 11, Bath, between Corning and Hammondsport: 40 RV sites with full hook-ups and \"20, 30, and 50 amp electric service\", pull-through and back-in; 15 cabin and lodging options and 6 tent sites; \"Swimming pool, splash pool, arcade, barbecue pit, playground, recreation hall, and a giant jump pillow\"; open year-round. Campspot lists it 22 miles from Watkins Glen."},{"name":"Courtyard by Marriott Horseheads","source":"https://hotelguides.com/attraction-maps/new-york/map-hotels-near-watkins-glen-state-park-ny.html","accessed":"2026-10-03","si":["family","senior"],"booking_route":"marriott.com (brand booking; not fetched - HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":33,"blurb":"Listed by HotelGuides at \"202 Colonial Drive, Horseheads, NY 14845\", \"14 miles from Watkins Glen State Park\". Marriott''s own page refused the fetch (HTTP 403), so nothing else about the property is stated here."},{"name":"Hampton Inn Horseheads","source":"https://hotelguides.com/attraction-maps/new-york/map-hotels-near-watkins-glen-state-park-ny.html","accessed":"2026-10-03","si":["family","senior"],"booking_route":"hilton.com (brand booking; not fetched - HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":34,"blurb":"Listed by HotelGuides at \"51 Arnot Road, Horseheads, NY 14845\", \"14 miles from Watkins Glen State Park\". Hilton''s own page refused the fetch (HTTP 403), so nothing else about the property is stated here."},{"name":"Fairfield Inn & Suites by Marriott Horseheads","source":"https://hotelguides.com/attraction-maps/new-york/map-hotels-near-watkins-glen-state-park-ny.html","accessed":"2026-10-03","si":["family","senior"],"booking_route":"marriott.com (brand booking; not fetched - HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":35,"blurb":"Listed by HotelGuides at \"1600 County Route 64, Horseheads, NY 14845\", \"15 miles from Watkins Glen State Park\". Marriott''s own page refused the fetch (HTTP 403), so nothing else about the property is stated here."},{"name":"Sturdy footwear for the Gorge Trail","source":"https://parks.ny.gov/visit/state-parks/watkins-glen-state-park","accessed":"2026-10-03","si":["hiking","adventure","family"],"booking_route":"affiliate referral to rei.com (AvantLink) or amazon.com (Associates)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":4,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":36,"blurb":"NY State Parks on the gorge tour: \"You''ll tour a mile of the gorge trail that follows Glen Creek past water-sculpted rocks, through tunnels, next to and actually under two waterfalls. There are many beautiful stone steps on this trail, making it a difficult hike for some visitors.\" The agency''s hiking advice (https://nystateparks.blog/tag/hiking-safety/): \"Wear sturdy, yet comfortable shoes or boots, bring water and snacks\"."},{"name":"Rain shell for walking under the falls","source":"https://parks.ny.gov/visit/state-parks/watkins-glen-state-park","accessed":"2026-10-03","si":["hiking","glamping","family"],"booking_route":"affiliate referral to rei.com (AvantLink) or amazon.com (Associates)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":4,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":37,"blurb":"The Gorge Trail runs \"next to and actually under two waterfalls\" (NY State Parks). For a camping stay the agency says: \"Include items like first aid essentials, sunscreen, raingear, and any medications you take.\" (https://nystateparks.blog/2025/05/20/know-before-you-go-tips-for-safe-fun-outdoor-recreation-this-summer/)"},{"name":"Daypack with water and a first-aid kit","source":"https://nystateparks.blog/tag/hiking-safety/","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"affiliate referral to deuter (AvantLink) or rei.com","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":8,"commission_basis":"published","wells":["gear"],"draw_rank":38,"blurb":"NY State Parks: \"Wear sturdy, yet comfortable shoes or boots, bring water and snacks, and perhaps carry a camera to capture what you see.\" \"Having a small first-aid kit available in case of an emergency is never a bad idea.\" For the rim trails above the gorge."},{"name":"REI Co-op, Ithaca","source":"https://www.tradeandindustrydev.com/region/new-york/news/ny-outdoor-retailer-rei-co-op-open-new-location-32197","accessed":"2026-10-03","si":["hiking","adventure","glamping"],"booking_route":"walk-in store; online purchases via rei.com","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["gear","shop"],"draw_rank":39,"blurb":"Announced for Ithaca in summer 2024 with \"apparel, gear and expertise for camping, cycling, running, fitness, hiking, paddling, climbing, snowsports and more\"; \"certified mechanics will tune and repair equipment through a full-service bike, ski and snowboard shop.\" The rei.com store page returned HTTP 403 today, so the address and hours were not read."}],"faq":[{"q":"Is Watkins Glen State Park free?","a":"No. The state charges a vehicle entry fee of \"$10 per vehicle\", which includes pool access.","source":"https://parks.ny.gov/parks/watkinsglen/details.aspx","accessed":"2026-10-03"},{"q":"How long is the Watkins Glen State Park trail?","a":"NY State Parks describes \"The Gorge Trail with 19 waterfalls in a 1-mile stretch\"; within two miles the glen descends 400 feet past 200-foot cliffs.","source":"https://parks.ny.gov/visit/state-parks/watkins-glen-state-park","accessed":"2026-10-03"},{"q":"How long does it take to walk Watkins Glen State Park?","a":"The Gorge Trail takes \"About 1.5 to 2 hours one way, depending on stops\", says the county visitor bureau, which suggests starting at the main entrance and returning by the South Rim Trail.","source":"https://www.explorewatkinsglen.com/watkins-glen-state-park/","accessed":"2026-10-03"},{"q":"Is Watkins Glen State Park open in November?","a":"The park is \"Open year round dawn to dusk\", but \"The Gorge Trail with 19 waterfalls in a 1-mile stretch will close for the season on October 25, 2026\" and re-opens in mid to late May. The North and South Rim trails stay open year-round, with no gorge or waterfall access November to May.","source":"https://parks.ny.gov/parks/watkinsglen/details.aspx","accessed":"2026-10-03"},{"q":"Can you bring dogs to Watkins Glen State Park?","a":"Yes, but not on the gorge: \"Pets are not allowed on the Gorge Trail. A maximum of two pets are allowed in campsites and day use areas (except the Gorge Trail)\". Pets must be supervised, on a leash no longer than 6 feet, with proof of rabies vaccination.","source":"https://parks.ny.gov/visit/state-parks/watkins-glen-state-park","accessed":"2026-10-03"},{"q":"Can you camp at Watkins Glen State Park?","a":"Yes. Tent and trailer sites are $18-$30 per night and rustic cabins $58 per night with a 3-night minimum, plus an out-of-state fee; the 2026 season opened May 8, and reservations are through ReserveAmerica or 1-800-456-2267.","source":"https://parks.ny.gov/parks/watkinsglen/details.aspx","accessed":"2026-10-03"},{"q":"Can you swim at Watkins Glen State Park?","a":"In the park''s pool. Its 2026 season ran June 27 to September 7, weekdays 12:00 p.m. to 5:45 p.m. and weekends 11:30 a.m. to 6:45 p.m., and entry is included in the $10 vehicle fee. The state''s page names no swimming in the gorge.","source":"https://parks.ny.gov/visit/state-parks/watkins-glen-state-park","accessed":"2026-10-03"},{"q":"What time is Watkins Glen State Park open?","a":"\"Open year round dawn to dusk.\"","source":"https://parks.ny.gov/visit/state-parks/watkins-glen-state-park","accessed":"2026-10-03"},{"q":"What is the best time of day to visit Watkins Glen State Park?","a":"\"Arrive early in the morning to avoid crowds, especially on weekends and peak summer months,\" advises the county visitor bureau.","source":"https://www.explorewatkinsglen.com/watkins-glen-state-park/","accessed":"2026-10-03"},{"q":"Where do you enter Watkins Glen State Park?","a":"There are three entrances, linked by the park shuttle when it runs: \"Main- 1009 N. Franklin St, Watkins Glen, NY 14891 South- 3530 Route 419, Watkins Glen, NY 14891 Upper- 3310 Route 409, Watkins Glen, NY 14891\". The shuttle is $6 per person one way.","source":"https://parks.ny.gov/parks/watkinsglen/details.aspx","accessed":"2026-10-03"}],"seo":{"meta_title":"Watkins Glen State Park: the Gorge Trail, Seneca Lake & The Glen | TravelWell","meta_description":"The 1-mile Gorge Trail past 19 waterfalls, its 2026 season, park fees, dogs and camping, plus Seneca Lake wineries, cruises and the racetrack.","slug":"watkins-glen-state-park-new-york","primary_keyword":"Watkins Glen State Park","jsonld_type":"TouristDestination"},"hero":{"query":"Watkins Glen State Park gorge trail"}}'::jsonb, 38),
  ('shenandoah-virginia', '12A', 'Shenandoah National Park', 'United States', 'Skyline Drive and the Old Rag scramble', 'future', 'verified', 'mountainValley', 'Mid-Atlantic', '{"hiking","glamping","family","adventure","parks"}', '{"serene","pastoral","adventurous"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Skyline Drive","source":"https://www.nps.gov/shen/planyourvisit/driving-skyline-drive.htm","accessed":"2026-10-02","si":["family","motoring","senior"],"commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"105 miles along the crest of the Blue Ridge, mileposts 0 (Front Royal) to 105, 35 mph in most places, four entrances; Marys Rock Tunnel (mile 32.2) has a maximum clearance of 12''8\"; the NPS FAQ counts over 75 scenic overlooks"},{"name":"Old Rag Mountain (day-use ticket March 1 - November 30)","source":"https://www.nps.gov/shen/planyourvisit/faqs-oldrag.htm","accessed":"2026-10-02","si":["adventure","hiking"],"commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":2,"blurb":"rock scrambles and 360-degree views in the Shenandoah Wilderness; $2.00 ticket per person of any age via Recreation.gov or 877-444-6777, 800 a day - 400 released 30 days ahead and 400 released 5 days ahead, daily at 10:00 a.m.; separate from the entrance pass; the NPS calls the summit hike \"physically demanding and also dangerous if you have not planned properly\""},{"name":"Big Meadows","source":"https://www.nps.gov/places/big-meadows.htm","accessed":"2026-10-02","si":["family","wildlife","hiking"],"commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"a high-elevation meadow and National Historic Landmark with the Byrd Visitor Center, Big Meadows Wayside and Lodge, campground, picnic ground and trails; the NPS names wildlife, wildflowers and stargazing; gas at Big Meadows Wayside (mile 51)"},{"name":"Skyland (mile 41.7)","source":"https://www.nps.gov/places/000/skyland.htm","accessed":"2026-10-02","si":["senior","family","romance"],"commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","eat"],"draw_rank":6,"blurb":"the resort George Freeman Pollock marketed from the 1890s, older than the park itself; at 3,680 feet, which the concessioner calls the highest elevation on the drive; Pollock Dining Room, Mountain Taproom, amphitheater; 2026 season March 30 to November 8"},{"name":"Dark Hollow Falls (mile 50.7)","source":"https://www.nps.gov/thingstodo/dark-hollow-falls.htm","accessed":"2026-10-02","si":["hiking","family"],"commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"a 1.4-mile circuit, 440 feet of elevation gain, rated moderate, about 1 hour 15 minutes; the NPS: \"This trail is short, but very steep and rocky. The return climb is challenging!\"; pets are not allowed"},{"name":"The Appalachian Trail through Shenandoah","source":"https://www.nps.gov/shen/faqs.htm","accessed":"2026-10-02","si":["hiking","expedition","adventure"],"commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"101 miles of the Appalachian Trail inside the park, part of over 500 miles of trail, marked with white blazes"},{"name":"Limberlost Trail","source":"https://www.nps.gov/shen/planyourvisit/accessibility.htm","accessed":"2026-10-02","si":["senior","family","hiking"],"commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"the park''s fully accessible circuit hike through a section of forest"},{"name":"Fall colour on the Blue Ridge","source":"https://www.nps.gov/shen/faqs.htm","accessed":"2026-10-02","si":["family","hiking","motoring","senior"],"commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"the NPS says colours are generally most brilliant around the 2nd or 3rd week of October"},{"name":"Fee-free days, October 27 and November 11, 2026","source":"https://www.nps.gov/shen/planyourvisit/special_events.htm","accessed":"2026-10-02","si":["culture","family"],"commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":59,"blurb":"the last two NPS fee-free days of 2026 at Shenandoah - Theodore Roosevelt''s birthday and Veterans Day; the park''s 2026 events also included its 90th Anniversary on July 3"},{"name":"Skyland Stables horseback and pony rides (park concessioner)","source":"https://www.goshenandoah.com/activities-events/horseback-riding","accessed":"2026-10-02","si":["family","senior"],"commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":16,"blurb":"one-hour guided rides from Skyland Stables (mile 42.5), May 1 to October 25, 2026, $89.99 plus tax; riders at least 4''10\" and under 250 lbs; 15-minute pony rides for children 5 and up at $9.99 plus tax"},{"name":"Big Meadows Lodge (mile 51)","source":"https://www.goshenandoah.com/lodging/big-meadows-lodge","accessed":"2026-10-02","si":["senior","family","romance"],"commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","eat"],"draw_rank":8,"blurb":"main lodge rooms, Blackrock premium rooms, suites and five standalone cabins, with the Spottswood Dining Room and New Market Taproom; 2026 season May 4 to November 29"},{"name":"Lewis Mountain Cabins (mile 57.5)","source":"https://www.goshenandoah.com/lodging/lewis-mountain-cabins","accessed":"2026-10-02","si":["family","hiking"],"commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":17,"blurb":"rustic furnished cabins with private baths and grill areas, plus a bunk-bed Hiker''s Cabin; concessioner lists the 2026 season as April 10 to November 8, while the NPS hours page (updated September 22, 2026) says \"Cabins are closed for the season\""},{"name":"PATC primitive cabins","source":"https://www.nps.gov/shen/planyourvisit/lodging.htm","accessed":"2026-10-02","si":["adventure","hiking"],"commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":23,"blurb":"six primitive cabins in the park maintained by the Potomac Appalachian Trail Club, with mattresses, blankets, cookware, pit toilets and spring water, reserved through the PATC"},{"name":"Backcountry camping by permit","source":"https://www.nps.gov/shen/planyourvisit/backcountry-camping.htm","accessed":"2026-10-02","si":["expedition","hiking","adventure"],"commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":22,"blurb":"overnight backcountry stays need a permit bought through Recreation.gov; the old paper-permit system \"is no longer in effect\""},{"name":"Mathews Arm Campground (NPS)","source":"https://www.nps.gov/shen/planyourvisit/campground-reservations.htm","accessed":"2026-10-02","si":["family","hiking"],"commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":19,"blurb":"mix of reservable and first-come sites; Recreation.gov releases 50% six months ahead, 25% two weeks ahead, 25% four days ahead; no reservations within 48 hours; 2026 season April 29 to November 1"},{"name":"Big Meadows Campground (NPS)","source":"https://www.nps.gov/shen/planyourvisit/campground-reservations.htm","accessed":"2026-10-02","si":["family","hiking"],"commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":18,"blurb":"by reservation only on Recreation.gov (rangers can make limited on-site reservations); 2026 season March 25 to November 29"},{"name":"Lewis Mountain Campground (NPS)","source":"https://www.nps.gov/shen/planyourvisit/campground-reservations.htm","accessed":"2026-10-02","si":["family","hiking"],"commission_status":"none","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":21,"blurb":"self-registration, first-come, first-served - \"Sites can not be reserved\"; 2026 season March 26 to November 22"},{"name":"Loft Mountain Campground (NPS)","source":"https://www.nps.gov/shen/planyourvisit/campground-reservations.htm","accessed":"2026-10-02","si":["family","hiking"],"commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":20,"blurb":"mix of reservable and first-come sites on Recreation.gov''s phased six-month, two-week and four-day release; 2026 season April 29 to November 1"},{"name":"Postcard Cabins Shenandoah (formerly Getaway)","source":"https://www.marriott.com/en-us/hotels/chosh-postcard-cabins-shenandoah-outdoor-collection-bonvoy/overview","accessed":"2026-10-02","si":["glamping","romance","family"],"commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":12,"blurb":"both getaway.house and postcardcabins.com/shenandoah now redirect to Marriott''s Outdoor Collection, the latter to a property page titled Postcard Cabins Shenandoah; LISTING-LEVEL ONLY - the property page returned 403 and no address, distance or cabin detail was read"},{"name":"Front Royal Outdoors glamping tents","source":"https://frontroyaloutdoors.com/glamping/","accessed":"2026-10-02","si":["glamping","family","adventure"],"commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":25,"blurb":"three glamping tents (Blue Ridge, Massanutten, Valley), each sleeping 5, \"on a bluff over the South Fork of the Shenandoah River\" with views of Massanutten and Shenandoah National Park; $125/night, March 1 to November 30, 2-night minimum"},{"name":"Spacious Skies Shenandoah Views, Luray","source":"https://spaciousskiescampgrounds.com/campgrounds/shenandoah-views/","accessed":"2026-10-02","si":["glamping","family","motoring"],"commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":14,"blurb":"four deluxe glamping yurts (including a couple''s yurt and family/group yurts), two deluxe cabins, RV and tent sites at 3402 Kimball Rd, with pools and a jumping pillow; Skyline Drive described as \"a short drive away\""},{"name":"#1 Rock Tavern River Kamp, Luray","source":"https://www.hipcamp.com/en-US/land/virginia-1-rock-tavern-river-kamp-4y0zhoyq","accessed":"2026-10-02","si":["glamping","family","adventure"],"commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":31,"blurb":"four riverside yurts sleeping 4-7 on 1.5 acres on the South Fork, with AC/heat and a shared bathhouse; on-site tubing and kayaking; listed at about 20 minutes to Thornton Gap; LISTING ONLY (Hipcamp)"},{"name":"South River Farm Campground, Front Royal","source":"https://www.hipcamp.com/en-US/land/virginia-south-river-farm-campground-pw1hrwoe","accessed":"2026-10-02","si":["glamping","motoring"],"commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":34,"blurb":"furnished riverside yurts, 30 tent sites and 14 full-hookup RV sites on 120 acres along the South Fork; listed within a 30-minute drive of the park''s North Entrance; LISTING ONLY (Hipcamp)"},{"name":"Big Dipper Ranch, Etlan","source":"https://www.hipcamp.com/en-US/land/virginia-big-dipper-ranch-camping-glamping-zwjhvx1e","accessed":"2026-10-02","si":["glamping","hiking","romance"],"commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":30,"blurb":"four safari-style glamping tents on 23 acres in Madison County, each sleeping 4 with a private composting toilet, a spring-fed pond and dark skies; listed at 10-15 minutes to the Old Rag trailhead; LISTING ONLY (Hipcamp)"},{"name":"Watercress Inn at Landon Farm, Etlan","source":"https://www.hipcamp.com/en-US/land/virginia-watercress-inn-at-landon-farm-r57hl9xx","accessed":"2026-10-02","si":["glamping","family"],"commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":35,"blurb":"a glamping cabin, walk-in cottage and barn studio plus tent and RV sites on a 120-acre working farm, with a farm store, farm tours and bike rentals; LISTING ONLY (Hipcamp)"},{"name":"Luray RV Resort on Shenandoah River","source":"https://www.lurayrvresortshenandoahriver.com/","accessed":"2026-10-02","si":["glamping","family","adventure"],"commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":13,"blurb":"glamping tents, Airstream rentals, cabins, a cottage, riverfront tent sites and full-hookup RV sites on 3/4 mile of river frontage at 4253 US-211, with on-site tubing; less than 15 minutes from the park by its own account; 2026 season March 20 to November 29"},{"name":"Yogi Bear''s Jellystone Park, Luray (cabins)","source":"https://www.campluray.com/","accessed":"2026-10-02","si":["glamping","motoring"],"commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":26,"blurb":"nine luxury cabin types sleeping up to 19, plus RV and tent sites, at 2250 U.S. 211 East, with a Water Zone, zip line and outdoor movie theater; 2026 season March 27 to November 29; 10 minutes from Luray Caverns by its own account"},{"name":"Shenandoah River State Park yurts","source":"https://www.hipcamp.com/en-US/state-park/united-states/virginia/shenandoah-river/all","accessed":"2026-10-02","si":["glamping","adventure"],"commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":27,"blurb":"Virginia state park near Front Royal with yurts, tent and RV camping, 5.2 miles of river shoreline and views of Shenandoah National Park and Massanutten; LISTING ONLY - the Virginia DCR page returned 403, so this rests on a Hipcamp summary"},{"name":"Rockingham Retreats - Glamping at the Cave, McGaheysville","source":"https://www.hipcamp.com/en-US/land/virginia-rockingham-retreats-glamping-at-the-cave-mxvhmpxp","accessed":"2026-10-02","si":["glamping","family"],"commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":46,"blurb":"glamping tents near McGaheysville in the Harrisonburg area; SEARCH-LISTING ONLY - its Hipcamp page did not load and no detail was read"},{"name":"Gooney Creek Campgrounds, Front Royal","source":"https://www.hipcamp.com/en-US/land/virginia-gooney-creek-campgrounds-j29hoj9v","accessed":"2026-10-02","si":["family","motoring"],"commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":44,"blurb":"45 sites - 19 tent, 24 RV with hookups at select sites, and a tiny house - at 7122 Stonewall Jackson Hwy, with creek access; open April 1 to October 31; listed within 30 minutes of Dickey Ridge; LISTING ONLY (Hipcamp)"},{"name":"Sitka Spruce Farms, Front Royal","source":"https://www.hipcamp.com/en-US/land/virginia-sitka-spruce-farms-dw9hqelk","accessed":"2026-10-02","si":["family","glamping"],"commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":45,"blurb":"six dispersed tent sites and a tiny house on a farm with horses, alpacas and goats, with add-on animal feeding and kayak rentals; LISTING ONLY (Hipcamp)"},{"name":"Endless Caverns RV Resort, New Market","source":"https://www.endlesscaverns.com/","accessed":"2026-10-02","si":["family","motoring"],"commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":42,"blurb":"RV sites, cottages and long-term stays on 265 acres at 1800 Endless Caverns Road, managed by Blue Water Development; distance to the park not stated"},{"name":"Misty Mountain Camp Resort","source":"https://mistymountaincampresort.com/","accessed":"2026-10-02","si":["family","motoring","glamping"],"commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":43,"blurb":"cabins, RV and tent sites and a bunk house \"at the foot of the Blue Ridge Mountains near historic Charlottesville\"; season March 11 to November 24; no address or distance to the park stated on its homepage"},{"name":"Luray Caverns","source":"https://luraycaverns.com/","accessed":"2026-10-02","si":["family","senior","culture"],"commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":9,"blurb":"self-guided cavern tour at 101 Cave Hill Road, open daily year-round, with the Car & Carriage Caravan Museum, Shenandoah Heritage Village, a garden maze and rope adventure park; adults $36, seniors $34, children 6-12 $18"},{"name":"Skyline Caverns, Front Royal","source":"https://skylinecaverns.com/","accessed":"2026-10-02","si":["family","senior"],"commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":29,"blurb":"a cavern with anthodite formations, which it calls \"one of the few places in the world\" to host them; adult tours $30, child $15, plus a miniature train and mirror maze"},{"name":"Shenandoah Caverns, Quicksburg","source":"https://www.shenandoahcaverns.com/","accessed":"2026-10-02","si":["family","culture"],"commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":40,"blurb":"guided cavern tours plus American Celebration on Parade, a gem sluice and a 1950s-style cafe, at 261 Caverns Road, 1 mile from I-81 exit 269"},{"name":"Front Royal Outdoors (river trips)","source":"https://frontroyaloutdoors.com/","accessed":"2026-10-02","si":["adventure","family"],"commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":15,"blurb":"tubing, kayaking, canoeing, rafting, SUP and fishing on the Shenandoah from 8567 Stonewall Jackson Hwy, mid-March to early November; tubing from $32 per tube, half-day trips from $41 per vessel"},{"name":"Downriver Canoe Company, Bentonville","source":"https://downriver.com/","accessed":"2026-10-02","si":["adventure","family"],"commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":28,"blurb":"canoe, kayak, raft and tube trips, river camping, shuttles and bike rentals at 884 Indian Hollow Rd; year-round, closed October 19-23, 2026; minimum age 5"},{"name":"Shenandoah River Adventures, Shenandoah VA","source":"https://www.shenandoahriveradventures.com/","accessed":"2026-10-02","si":["adventure","family"],"commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":41,"blurb":"canoe, kayak and tubing trips, fishing trips, a 3-acre tent camping lot and multi-day Aqua-Blaze trips east of Harrisonburg; open year-round 2026, 9 a.m. to 5 p.m. daily"},{"name":"Shenandoah Bicycle Company, Harrisonburg","source":"https://www.shenandoahbicycle.com/","accessed":"2026-10-02","si":["sports","adventure"],"commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["gear"],"draw_rank":58,"blurb":"bike shop at 135 South Main Street with a rentals section and local route information; rental types not stated on its homepage"},{"name":"Glen Manor Vineyards, Front Royal","source":"https://www.glenmanorvineyards.com/","accessed":"2026-10-02","si":["culture","wine","romance"],"commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":36,"blurb":"a five-generation Virginia Century Farm on the Blue Ridge''s western slope that borders the park to the east, 18 acres of vines at 2244 Browntown Road; open Wednesday to Sunday 11-5, groups of four maximum"},{"name":"Rappahannock Cellars, Huntly","source":"https://www.rappahannockcellars.com/","accessed":"2026-10-02","si":["culture","wine"],"commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":54,"blurb":"family-owned, woman-led, solar-powered winery at 14437 Hume Rd, open daily noon to 6pm"},{"name":"Pen Druid Fermentation, Sperryville","source":"https://www.pendruid.com/","accessed":"2026-10-02","si":["culture","culinary","wine"],"commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":50,"blurb":"wood-fired, spontaneous, barrel-fermented native beer, natural cider and wine at 278 Red Banks Ln; Friday 2-6, weekends 12-6"},{"name":"Basic City Beer Co., Waynesboro","source":"https://www.basiccitybeer.com/","accessed":"2026-10-02","si":["culture","culinary","group"],"commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":49,"blurb":"microbrewery with food, cocktails and a music venue at 1010 East Main St, the southern gateway town"},{"name":"Front Royal, the north entrance","source":"https://www.discoverfrontroyal.com/","accessed":"2026-10-02","si":["culture","family","hiking"],"commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":33,"blurb":"the town calls itself the \"North entrance to Skyline Drive\"; visitor center at 414 East Main Street"},{"name":"The Inn at Little Washington, Washington VA","source":"https://www.theinnatlittlewashington.com/","accessed":"2026-10-02","si":["culinary","romance","wine","ultra"],"booking_route":