insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('congaree-south-carolina', '12A', 'Congaree National Park', 'United States', 'Old-growth floodplain forest and synchronous fireflies', 'future', 'verified', 'mountainValley', 'The Carolinas & Lowcountry', '{"hiking","wildlife","adventure","family","parks"}', '{"serene","wild","adventurous"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Boardwalk Trail","source":"https://www.nps.gov/cong/planyourvisit/Trail-Information.htm","accessed":"2026-10-03","si":["hiking","family","senior","wildlife"],"booking_route":"none needed - free park trail; entrance to the park is free","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"2.6 miles round trip, rated EASY: \"The boardwalk begins on a bluff at the Harry Hampton Visitor Center with an elevated section that leads down into the old-growth bottomland hardwood forest\"; bald cypress and tupelo in the lowest elevations; \"The boardwalk has benches along the way and is wheelchair and stroller accessible.\""},{"name":"Synchronous Firefly Viewing Event","source":"https://www.nps.gov/cong/fireflies.htm","accessed":"2026-10-03","si":["wildlife","family","hiking"],"booking_route":"Recreation.gov lottery (recreation.gov/ticket/facility/300008), one entry per household","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":2,"blurb":"\"there are only three species of synchronous fireflies that can be found in North America\"; the 2026 event ran May 13-20, entry by Recreation.gov lottery only - $1 non-refundable application, $24 more if awarded ($25 total), 145 passes per night, one passenger vehicle of up to 8 people per pass; viewing \"best just after dark, usually between 9:00 p.m. and 10:00 p.m.\""},{"name":"Cedar Creek Canoe Trail","source":"https://www.nps.gov/cong/planyourvisit/canoeing.htm","accessed":"2026-10-03","si":["adventure","wildlife","family"],"booking_route":"none needed - free, bring-your-own boat from Bannister Bridge or South Cedar Creek landings","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"\"The marked Cedar Creek Canoe Trail winds approximately 15 miles through the Congaree Wilderness, starting at Bannister''s Bridge and going all the way to the Congaree River\"; through \"some of the tallest trees in eastern North America\". Bring your own boat - \"the park does not rent out kayaks or canoes\"."},{"name":"Harry Hampton Visitor Center","source":"https://developer.nps.gov/api/v1/visitorcenters?parkCode=cong","accessed":"2026-10-03","si":["family","senior","hiking"],"booking_route":"none needed - free, 100 National Park Road, Hopkins, SC 29061, 803 776-4396","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"Open 9:00 a.m. to 5:00 p.m. daily, closed New Year''s Day, Washington''s Birthday, Columbus Day, Thanksgiving Day and Christmas Day; \"The majority of trails begin from the Harry Hampton Visitor Center\"; free self-guided Boardwalk brochure, park store, loaner wheelchairs."},{"name":"Champion trees of the old-growth forest","source":"https://www.nps.gov/cong/faqs.htm","accessed":"2026-10-03","si":["hiking","wildlife","senior"],"booking_route":"none needed - seen from the Boardwalk and park trails","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"\"The average canopy height of the forest here is over 100 feet tall, and it contains the highest concentration of champion-sized trees anywhere in North America. The tallest tree in the park is the National Champion loblolly pine, which when last measured, is 170 feet tall and has a circumference of over 15 feet.\""},{"name":"Weston Lake Trail (#3)","source":"https://www.nps.gov/cong/planyourvisit/Trail-Information.htm","accessed":"2026-10-03","si":["hiking","wildlife"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":6,"blurb":"4.5 miles round trip, MODERATE: \"great views of Cedar Creek where otters and wading birds are regularly observed\"; the eastern portion follows a cypress-tupelo slough \"where many cypress knees can be seen sticking up out of the water.\""},{"name":"Longleaf Campground","source":"https://www.nps.gov/cong/planyourvisit/camping.htm","accessed":"2026-10-03","si":["hiking","group","family","adventure"],"booking_route":"Recreation.gov or 1-877-444-6777","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":7,"blurb":"\"10 individual and 4 group camping sites\" at $15 and $25 a night; \"Each site has a fire ring and a picnic table\"; two vault toilets, no running water on site; tents and hammocks only, sleeping in vehicles prohibited; Senior and Access Pass holders receive 50% off. One accessible site (Site 1)."},{"name":"Kingsnake Trail (#6)","source":"https://www.nps.gov/cong/planyourvisit/Trail-Information.htm","accessed":"2026-10-03","si":["hiking","wildlife","adventure"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":8,"blurb":"12 miles, DIFFICULT: \"a favorite trail for birders because of the diverse vegetation and proximity to Cedar Creek\"; current condition \"MAY BE DIFFICULT TO FOLLOW IN SOME AREAS; USE CAUTION\"."},{"name":"Oakridge Trail (#4)","source":"https://www.nps.gov/cong/planyourvisit/Trail-Information.htm","accessed":"2026-10-03","si":["hiking","wildlife"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"7.1 miles round trip, DIFFICULT: \"Passing through a rich stretch of old-growth forest, this trail traverses a subtle ridge where a variety of large oak trees grow\"; low-lying sloughs make it \"great for viewing wildlife like deer and wild turkey.\""},{"name":"Boggy Gut Trail (#5)","source":"https://www.nps.gov/cong/planyourvisit/Trail-Information.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"11.1 miles round trip, DIFFICULT: \"This trail leads to the Congaree River\"; \"Approximately ten times a year the river overflows its banks and pulses water through the bottomland forest. When the river is low, a large sandbar may be visible.\" Current condition notes \"NUMEROUS TREES DOWN DUE TO RECENT STORMS\"."},{"name":"Bates Ferry Trail (#7)","source":"https://www.nps.gov/cong/planyourvisit/Trail-Information.htm","accessed":"2026-10-03","si":["hiking","culture"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":11,"blurb":"2.2 miles round trip, EASY, from Route 601 in the eastern section: follows \"a 1920''s ferry road south to the Congaree\", a remnant of the colonial-era ferries \"which once crossed near here\"; the river bank \"is steep and could potentially be slippery.\" RVs cannot use its parking lot."},{"name":"Fork Swamp Trail (#9)","source":"https://www.nps.gov/cong/planyourvisit/Trail-Information.htm","accessed":"2026-10-03","si":["hiking","wildlife"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":12,"blurb":"0.6 miles, MODERATE: \"runs alongside the southern channel of Bates Old River, an oxbow lake created by a hurricane in 1852.\""},{"name":"Firefly Trail (#10)","source":"https://www.nps.gov/cong/planyourvisit/Trail-Information.htm","accessed":"2026-10-03","si":["wildlife","hiking","family"],"booking_route":"none needed outside the firefly event; event nights need a Recreation.gov pass","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":13,"blurb":"1.8 miles round trip, EASY: \"Visitors are treated to a magical light show produced by synchronous fireflies along this trail in late spring\"; one of the four trails the NPS lists as not subject to periodic flooding."},{"name":"Bluff Trail (#1)","source":"https://www.nps.gov/cong/planyourvisit/Trail-Information.htm","accessed":"2026-10-03","si":["hiking","family","senior"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":14,"blurb":"1.8 miles round trip, EASY: an upland loop north of the Visitor Center through \"a young forest of loblolly and longleaf pines. Evidence of prescribed burns can be found along this trail.\""},{"name":"Sims Trail (#2)","source":"https://www.nps.gov/cong/planyourvisit/Trail-Information.htm","accessed":"2026-10-03","si":["hiking","culture"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":15,"blurb":"3.2 miles round trip, EASY: follows an old gravel road from the Bluff Trail to Cedar Creek, crossing the boardwalk twice; the clearing at the Weston Lake junction \"was the site of a hunt club where Harry Hampton was once a member.\""},{"name":"Bluff Campground","source":"https://www.nps.gov/cong/planyourvisit/camping.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"Recreation.gov or 1-877-444-6777","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":16,"blurb":"\"6 individual campsites\" at $10 a night, \"Each site has a fire ring and picnic table\"; no restroom or water; about a 1-mile hike from the parking area."},{"name":"Backcountry camping in the Congaree Wilderness","source":"https://www.nps.gov/cong/planyourvisit/permitsadnreservations.htm","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"free permit requested by email to the park, 72+ hours ahead","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":17,"blurb":"\"Camping in the backcountry is FREE and requires a permit\", requested by email at least 72 hours ahead; campers \"may select any suitable place, as long as they remain 100 feet away from Cedar Creek\"; 6 campers and 3 structures per site; \"Open fires are not permitted in the backcountry\". No permits are issued during the firefly event."},{"name":"Fishing in Congaree National Park","source":"https://www.nps.gov/cong/planyourvisit/fishing.htm","accessed":"2026-10-03","si":["adventure","wildlife"],"booking_route":"none needed in the park - a South Carolina fishing license is required (SCDNR)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":18,"blurb":"\"Fishing is allowed within Congaree National Park with a valid South Carolina fishing license\"; permitted in all areas but not \"from or within 25 feet of any man-made structure\"; motorized boats prohibited; no minnows, amphibians or fish eggs as bait; state fish-consumption advisories apply on the Congaree River."},{"name":"Congaree River Blue Trail","source":"https://www.americanrivers.org/river/congaree-river/","accessed":"2026-10-03","si":["adventure","wildlife"],"booking_route":"none needed - a public river trail; self-guided or with a Columbia outfitter","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":19,"blurb":"American Rivers: the trail runs the Congaree River''s 50 miles from near Columbia to Congaree National Park, where visitors can \"paddle 20 miles of the Blue Trail\"; it was \"the first Blue Trail established by American Rivers and our partners in 2007.\" The NPS calls it \"the 50-mile designated recreational paddle trail\"."},{"name":"Carolina Outdoor Adventures","source":"https://www.carolinaoutdooradventures.com/","accessed":"2026-10-03","si":["adventure","wildlife","family"],"booking_route":"FareHarbor (own website)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":20,"blurb":"Started in 2015 by owner/operator Billy Easterbrooks; calls itself \"one of a few companies permitted to operate in Congaree National Park\"; a Congaree National Park feature kayak trip plus seasonal \"Park after dark/Full Moon Paddles\". The NPS lists it for guided ~3-hour kayak tours daily at 9:30 am, meeting at South Cedar Creek Landing. Irmo, SC; 803-381-2293."},{"name":"J.K. Adventure Guides","source":"https://jkadventureguides.com/","accessed":"2026-10-03","si":["adventure","wildlife","family"],"booking_route":"FareHarbor (own website)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":21,"blurb":"\"Let us help you explore our rivers in Columbia, SC or Congaree National Park by Kayaking or Canoeing\"; trips listed for Congaree National Park, the Congaree, Saluda and Broad rivers and a Spider Lily trip. The NPS lists it for guided ~3-hour canoe and kayak tours at 9 am and 1 pm most days from South Cedar Creek Landing. (803) 397-0000."},{"name":"Palmetto Outdoor","source":"https://www.palmettooutdoor.com/","accessed":"2026-10-03","si":["adventure","family","wildlife"],"booking_route":"Peek (book.peek.com) from the own website","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":22,"blurb":"\"a tubing and canoe outfitter located in the heart of West Columbia''s River District\", offering a year-round \"guided Congaree National Park Canoe tour\". The NPS lists it for guided ~3-hour canoe tours at 11 am most days from South Cedar Creek Landing."},{"name":"River Runner Outdoor Center","source":"https://www.nps.gov/cong/planyourvisit/canoeing.htm","accessed":"2026-10-03","si":["adventure"],"booking_route":"pickup at store in Columbia (contact not read - own site down)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["gear"],"draw_rank":23,"blurb":"Listed by the NPS among outfitters for Cedar Creek: \"Mon-Sat 10am-6pm, Canoe and kayak rentals, pickup at store\" - the park itself does not rent boats. Its own website did not resolve when fetched."},{"name":"Harriet Barber House","source":"https://www.harrietbarberhouse.org/bio-our-history","accessed":"2026-10-03","si":["culture","senior","pilgrimage"],"booking_route":"tours via the site''s DONATIONS/TOURS page (hours and terms not read)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":24,"blurb":"In Hopkins, named by the NPS as part of the Reconstruction Era National Historic Network. Its own history: \"In 1872 Samuel Barber, a former slave, purchased lot number 35, which contained forty-two and one-half acres of the Hopkins Tract, one of six tracts in Lower Richland County purchased by the South Carolina Land Commission for redistribution\"; Harriet Barber made the final payment and received title in 1879."},{"name":"Poinsett State Park","source":"https://southcarolinaparks.com/poinsett","accessed":"2026-10-03","si":["hiking","family","adventure"],"booking_route":"reserve.southcarolinaparks.com or 803.494.8177","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":25,"blurb":"Wedgefield: \"1000 acres of diverse landscape\" called the \"mountains of the midlands\"; 10-acre Levi Mill Lake with paddleboard, kayak, canoe and jon boat rentals; \"25.6 miles of trails\"; \"50 campsites are available with 24 including power and 26 without power\" plus \"5 Rustic CCC Cabins\"; admission \"$3 adults\"; hours \"9am-dark, year round\"."},{"name":"Sesquicentennial State Park","source":"https://southcarolinaparks.com/sesqui","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"reserve.southcarolinaparks.com or 803.788.2706","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":26,"blurb":"9564 Two Notch Rd, Columbia: \"1419 acres of parkland\" with a 30-acre lake for paddling and fishing, \"12 miles of hiking and biking trails\", \"78 standard campsites with electric and water for RVs or tents, 9 of which are full service\"; admission \"$6 adults\"; open \"8 a.m. - Sunset, daily\". Named by the NPS on its nearby-attractions page."},{"name":"Hotel Trundle","source":"https://www.hoteltrundle.com/","accessed":"2026-10-03","si":["culture","romance"],"booking_route":"own website booking (webrez.com) or phone","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":27,"blurb":"1224 Taylor Street, Columbia''s Main Street District: three restored historic buildings - the Rose Talbert Building (1914), Powell Furniture Building (1920) and Western Auto (1940); (803) 722-5000. The NPS places Columbia''s lodging \"approximately 20 minutes from the park\" (nps.gov/cong eating & sleeping)."},{"name":"Cozy RV Retreat with Fire Pit and Outdoor Deck","source":"https://glampinghub.com/unitedstatesofamerica/southeast/southcarolina/hopkins/cozy-rv-retreat-fire-pit-outdoor-deck-hopkins-sc/","accessed":"2026-10-03","si":["glamping","family"],"booking_route":"Glamping Hub enquiry form","commission_status":"none","commission":"affiliate","tier_absent_reason":"not-established","commission_basis":"published","wells":["stay"],"draw_rank":28,"blurb":"A Hopkins caravan for four on 2.5 wooded acres, \"20 minutes from downtown Columbia and 5 minutes from Congaree national park\"; one queen bedroom, fire pit, deck, Wi-Fi, pets allowed; check-in 3:00-4:00 PM. Listed as \"New\" with no reviews."},{"name":"Sweetwater Lake Campground","source":"https://www.hipcamp.com/en-US/land/south-carolina-sweetwater-lake-campground-mxvhwdwp","accessed":"2026-10-03","si":["glamping","family"],"booking_route":"Hipcamp","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":29,"blurb":"St. Matthews: glamping tents with \"queen size bed, crisp, clean linen, two hammocks, grill, fire pit and firewood\", plus RV and tent sites, a bathhouse with showers and a private 40-acre spring-fed lake; \"Only one mile off of I26 exit 139\"; 2-night minimum for glamping tents."},{"name":"Camp at The Farm - Outside Inn","source":"https://www.hipcamp.com/en-US/land/south-carolina-camp-at-the-farm-outside-inn-lz9hkz6r","accessed":"2026-10-03","si":["glamping","family","motoring"],"booking_route":"Hipcamp","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":30,"blurb":"Santee: a working farm of 63+ acres with 25 full-hook-up RV sites (28-75 ft), 2 glamping units (a canvas tent and a renovated vintage RV), \"nearly 2 miles of wooded walking trails\", bathhouse, laundry, and Highland cattle, goats, pigs and donkeys with scheduled farm tours."},{"name":"Big Rig Friendly RV Resort","source":"https://www.hipcamp.com/en-US/land/south-carolina-big-rig-friendly-rv-resort-y0zh66mm","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"Hipcamp","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":42,"blurb":"West Columbia: 10 RV sites with full hookups - \"20/30/50 Amp power service\" plus sewer and water - complimentary Wi-Fi, campfires permitted, pets welcome. Hipcamp lists it 21 miles from Gadsden."},{"name":"Motor Supply Co. Bistro","source":"https://motorsupplycobistro.com/","accessed":"2026-10-03","si":["culinary","romance"],"booking_route":"online reservations or (803) 256-6687","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":31,"blurb":"920 Gervais St., Columbia: farm-to-table since 1989 with sustainably sourced meats, house-made sauces and desserts and South Carolina seafood; \"Recommended in the 2025 MICHELIN Guide\"; brunch Fri-Sun, dinner nightly."},{"name":"The War Mouth","source":"https://thewarmouth.com/","accessed":"2026-10-03","si":["culinary","culture"],"booking_route":"walk-in; call ahead for groups of 6+ (803-569-6144)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":32,"blurb":"1209 Franklin Street, Columbia: \"whole-hog BBQ slowly cooked over hardwood embers, alongside dishes created from locally sourced produce\"; Mon 11:30 AM-9 PM, Tue-Sat 11:30 AM-10 PM, closed Sundays."},{"name":"Mr. Friendly''s New Southern Cafe","source":"https://mrfriendlys.com/","accessed":"2026-10-03","si":["culinary"],"booking_route":"Resy or 803-254-7828","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":33,"blurb":"2001-A Greene St, Historic Five Points, Columbia: \"Since 1995, we have been serving New Southern Cuisine in a sophisticated, yet casual environment\"; lunch weekdays, dinner Mon-Sat."},{"name":"Bourbon","source":"https://www.bourboncolumbia.com/","accessed":"2026-10-03","si":["culinary"],"booking_route":"walk-in only; 803-403-1404","commission_status":"none","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":34,"blurb":"1214 Main Street, Columbia: \"Cajun-Creole classics like gumbo, jambalaya, and étouffée\" and over 600 whiskeys; \"Bourbon is walk-in only\"."},{"name":"Lula Drake Wine Parlour","source":"https://www.luladrake.com/","accessed":"2026-10-03","si":["wine","romance","culinary"],"booking_route":"phone 803.606.1968 (no reservation method on the page)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":35,"blurb":"1635 Main Street, Columbia: a wine parlour open Tue-Thu 5-10 pm and Fri-Sat 5-11 pm; 803.606.1968."},{"name":"Soda City Market","source":"https://sodacitysc.com/","accessed":"2026-10-03","si":["culinary","family","culture"],"booking_route":"none needed - an open street market","commission_status":"none","tier_absent_reason":"not-sold","wells":["eat","shop"],"draw_rank":36,"blurb":"\"Columbia''s weekly Main Street event inspired by traditional European street markets\": every Saturday 9 a.m.-1 p.m. year-round on the 1300-1700 blocks of Main Street, about 200 vendors a week, each required to make or grow their own products."},{"name":"Riverbanks Zoo & Garden","source":"https://www.riverbanks.org/","accessed":"2026-10-03","si":["family","wildlife"],"booking_route":"own online ticketing (tickets.riverbanks.org)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":37,"blurb":"500 Wildlife Parkway, Columbia: about 3,000 animals and 5,700 plant varieties; open 9:00am-5:00pm on the day read; the Saluda Skyride closed October 5-9 for staff training."},{"name":"South Carolina State Museum","source":"https://www.scmuseum.org/visit","accessed":"2026-10-03","si":["culture","family","senior"],"booking_route":"own website tickets","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":38,"blurb":"301 Gervais Street, Columbia: \"The largest and most comprehensive museum in the state\", four floors of history, art, natural history and science; a 55ft digital-dome planetarium and a public observatory with a 1926 telescope; closed Mondays; $1 general admission on the first Sunday of each month."},{"name":"Friends of Congaree Swamp","source":"https://friendsofcongaree.org/","accessed":"2026-10-03","si":["wildlife","hiking"],"booking_route":"none needed - membership and information via the website","commission_status":"unknown","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":39,"blurb":"\"Advocates for Congaree National Park and its unique environment\" - stewards of the park, \"an International Biosphere Reserve, and a Globally Important Bird Area\"; hosts research symposiums and publishes trail guides to the Boardwalk Loop, Bluff Trail and Cedar Creek. PO Box 7746, Columbia; 803-331-3366."},{"name":"Congaree Riverkeeper","source":"https://www.congareeriverkeeper.org/","accessed":"2026-10-03","si":["wildlife","adventure"],"booking_route":"none needed - information and volunteering via the website","commission_status":"unknown","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":40,"blurb":"\"The river watchdog of the South Carolina Midlands, looking out for the Broad, Lower Saluda, and Congaree Rivers\" - river cleanups, water-quality monitoring and policy advocacy. 803.760.3357."},{"name":"The COMET Bus Route 47","source":"https://www.nps.gov/cong/planyourvisit/directions.htm","accessed":"2026-10-03","si":["family","senior"],"booking_route":"fares and schedules at catchthecometsc.gov (not read)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["move"],"draw_rank":41,"blurb":"\"The COMET offers regularly scheduled bus service to and from the park via Bus Route 47. The bus stop is located outside of the Harry Hampton Visitor Center near the middle parking lot\"; the NPS warns ride-share services \"may not provide pick up service from Congaree National Park.\""},{"name":"Courtyard by Marriott Cayce","source":"https://hotelguides.com/attraction-maps/south-carolina/map-hotels-near-congaree-national-park-sc.html","accessed":"2026-10-03","si":["family","senior"],"booking_route":"marriott.com (brand booking; not fetched - HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":43,"blurb":"Listed by HotelGuides at \"1125 Fort Congaree Trail, Cayce, SC 29033\", \"19 miles from Congaree National Park\". Marriott''s own page refused the fetch (HTTP 403), so nothing else about the property is stated here."},{"name":"SpringHill Suites by Marriott Fort Jackson Columbia","source":"https://hotelguides.com/attraction-maps/south-carolina/map-hotels-near-congaree-national-park-sc.html","accessed":"2026-10-03","si":["family","senior"],"booking_route":"marriott.com (brand booking; not fetched - HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":44,"blurb":"Listed by HotelGuides at \"170 East Exchange Blvd, I-77, Exit 9A, Columbia, SC 29209\", \"17 miles from Congaree National Park\". Marriott''s own page refused the fetch (HTTP 403), so nothing else about the property is stated here."},{"name":"Home2 Suites by Hilton Southeast Fort Jackson Columbia","source":"https://hotelguides.com/attraction-maps/south-carolina/map-hotels-near-congaree-national-park-sc.html","accessed":"2026-10-03","si":["family","senior"],"booking_route":"hilton.com (brand booking; not fetched - HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":45,"blurb":"Listed by HotelGuides at \"7340 Garners Ferry Road, I-77, Exit 9A, Columbia, SC 29209\", \"16 miles from Congaree National Park\". Hilton''s own page refused the fetch (HTTP 403), so nothing else about the property is stated here."},{"name":"Cedar Creek paddling kit (PFD, whistle, map and compass)","source":"https://www.nps.gov/cong/planyourvisit/canoe-trail-conditions.htm","accessed":"2026-10-03","si":["adventure","river"],"booking_route":"affiliate referral to rei.com (AvantLink); the boat itself rents from the Columbia outfitters the NPS names","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":46,"blurb":"NPS: \"Before beginning your trip, make sure that you have the proper equipment. Besides a canoe or kayak, you should have a personal flotation device (PFD), whistle, weather appropriate clothing, water, food, sunscreen and insect repellent.\" \"No matter the length of your trip, it is highly advisable to always carry a map and compass with you.\" Water levels \"can fluctuate as much as 10 feet\"; flood stage is set at 8 feet."},{"name":"Bug spray and sunscreen for the floodplain","source":"https://www.nps.gov/cong/planyourvisit/safety.htm","accessed":"2026-10-03","si":["hiking","river","family"],"booking_route":"affiliate referral to rei.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":47,"blurb":"NPS lists \"sunscreen and insect repellent\" in the paddler''s kit, and beyond the Ten Essentials: \"You may need additional items depending on current conditions and the activity in which you participate (e.g. life jacket/PFD, bug spray, personal locator beacon).\" Downed trees hide \"spiders, wasps and other stinging insects, and snakes\"."},{"name":"Backpacking stove for backcountry camping","source":"https://www.nps.gov/cong/planyourvisit/backcountry-camping.htm","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"affiliate referral to campsaver.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":7,"commission_pct_high":7,"commission_basis":"published","wells":["gear"],"draw_rank":48,"blurb":"NPS: \"Open fires are not permitted in the backcountry. Campers are permitted the use of a backpacking stove for cooking.\" There are no designated backcountry sites, and \"It is advisable to check the river forecast prior to your visit to ensure that a rise in water levels is not forecast.\""},{"name":"Personal locator beacon where the cell signal drops","source":"https://www.nps.gov/cong/planyourvisit/safety.htm","accessed":"2026-10-03","si":["hiking","adventure","river"],"booking_route":"affiliate referral to zoleo.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["gear"],"draw_rank":49,"blurb":"NPS names a \"personal locator beacon\" among the extras beyond the Ten Essentials, and warns: \"Cell service can be unreliable in the park, so you may have to find a place where there is reception, or send someone with a cell phone to make the call.\""}],"faq":[{"q":"Is Congaree National Park free?","a":"Yes. The NPS states: \"Entrance to Congaree National Park is free. There is no fee to enter the park.\" Camping, the picnic shelter and the firefly event carry their own fees.","source":"https://www.nps.gov/cong/planyourvisit/fees.htm","accessed":"2026-10-03"},{"q":"Can you camp in Congaree National Park?","a":"Yes, in tents or hammocks. Longleaf Campground has \"10 individual and 4 group camping sites\" ($15 and $25 a night) and Bluff Campground has \"6 individual campsites\" ($10), both reserved \"through Recreation.gov or by calling 1-877-444-6777\". Backcountry camping needs a free permit requested at least 72 hours ahead. RVs and sleeping in vehicles are not allowed.","source":"https://www.nps.gov/cong/planyourvisit/camping.htm","accessed":"2026-10-03"},{"q":"Can you kayak in Congaree National Park?","a":"Yes. \"The marked Cedar Creek Canoe Trail winds approximately 15 miles through the Congaree Wilderness, starting at Bannister''s Bridge and going all the way to the Congaree River.\" You bring your own boat or go with one of the outfitters the NPS lists.","source":"https://www.nps.gov/cong/planyourvisit/canoeing.htm","accessed":"2026-10-03"},{"q":"Can you rent kayaks at Congaree National Park?","a":"Not from the park: \"No, the park does not rent canoes or kayaks. Canoes or kayaks can be rented through outfitters in the city of Columbia.\"","source":"https://www.nps.gov/cong/faqs.htm","accessed":"2026-10-03"},{"q":"When is firefly season in Congaree National Park?","a":"\"Every year, Congaree National Park hosts synchronous fireflies for approximately two weeks between mid-May and mid-June.\" The 2026 viewing event ran May 13-20, with entry by a Recreation.gov lottery that opened April 7 and closed April 14.","source":"https://www.nps.gov/cong/fireflies.htm","accessed":"2026-10-03"},{"q":"What is the best time to visit Congaree National Park?","a":"The NPS says the park \"is best experienced in the spring and fall when temperatures are at their most comfortable and insects are generally not a problem.\" Fall colors peak \"between the end of October and early November\", and autumn water levels are \"ideal\" for paddling Cedar Creek.","source":"https://www.nps.gov/cong/planyourvisit/weather.htm","accessed":"2026-10-03"},{"q":"Is Congaree National Park dog friendly?","a":"Yes: \"Pets are allowed on all trails, including the boardwalk, as well as in the campgrounds.\" They must be on a leash no longer than 6 feet and never left unattended. No pets are allowed during the firefly event; service animals are welcome.","source":"https://www.nps.gov/cong/planyourvisit/pets.htm","accessed":"2026-10-03"},{"q":"Can you fish in Congaree National Park?","a":"Yes: \"Fishing is allowed within Congaree National Park with a valid South Carolina fishing license.\" It is not allowed \"from or within 25 feet of any man-made structure, including bridges, boardwalk, and overlooks\", and boats with inboard or outboard motors are prohibited.","source":"https://www.nps.gov/cong/planyourvisit/fishing.htm","accessed":"2026-10-03"},{"q":"What is the closest airport to Congaree National Park?","a":"\"The nearest major airport to Congaree National Park is Columbia Metropolitan Airport which is located approximately 30 minutes from the park.\" Charlotte Douglas and Charleston International are each about 2 hours away, per the NPS.","source":"https://www.nps.gov/cong/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"Is Congaree National Park a swamp?","a":"The NPS describes it as a floodplain: \"A floodplain, also known as a bottomland, is a low-lying area along a stream or river that will periodically be covered by water throughout the year. A swamp is an area that has significant areas of water flowing over it throughout the entire year... a floodplain will not always be a swamp.\"","source":"https://www.nps.gov/cong/faqs.htm","accessed":"2026-10-03"}],"seo":{"meta_title":"Congaree National Park: Boardwalk, Cedar Creek & Fireflies | TravelWell","meta_description":"Free entry, a 2.6-mile accessible boardwalk, 15 miles of Cedar Creek canoe trail, May''s synchronous fireflies by lottery, and where to camp and stay nearby.","slug":"congaree-national-park-south-carolina","primary_keyword":"Congaree National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Congaree National Park boardwalk"}}'::jsonb, 41),
  ('everglades-florida', '12A', 'Everglades National Park', 'United States', 'Sawgrass, mangroves and the Anhinga Trail', 'future', 'verified', 'mountainValley', 'Florida - Atlantic & the Keys', '{"wildlife","adventure","hiking","family","parks"}', '{"wild","tropical","adventurous","coastal"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Anhinga Trail","source":"https://www.nps.gov/places/anhinga-trail.htm","accessed":"2026-10-03","si":["wildlife","hiking","family","senior"],"booking_route":"none needed - covered by the park entrance pass","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"\"A self-guiding pavement and boardwalk trail winding through and over sawgrass marsh and freshwater slough\"; 0.8 miles (1,200 meters) round trip, wheelchair accessible; visitors may encounter \"alligators, fish, turtles, anhingas, and many other birds, especially during the winter\". At the Royal Palm area; pets not allowed."},{"name":"Shark Valley Tram Tour","source":"https://developer.nps.gov/api/v1/thingstodo?parkCode=ever","accessed":"2026-10-03","si":["wildlife","family","senior"],"booking_route":"own website (sharkvalleytramtours.com, \"Click to Book a Tram or Bike Tour\") or 305-221-8455","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":2,"blurb":"\"Guided two-hour tram tours are offered along a fifteen-mile loop trail\"; Adults $31, Seniors $24, Children (3-12) $16 per the NPS listing. The operator, Shark Valley Tram Tours, describes \"Park-trained naturalists\" and a stop at the halfway observation tower; open 8:30am - 6:00pm daily; 305-221-8455."},{"name":"Flamingo Lodge","source":"https://www.nps.gov/ever/learn/news/flamingo-grand-opening-announcement.htm","accessed":"2026-10-03","si":["wildlife","family","senior","romance"],"booking_route":"flamingoeverglades.com/flamingo-lodge-restaurant/ or 855-708-2207 (own site refused the fetch, HTTP 403)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":3,"blurb":"Opened October 27, 2023, built and run by \"Everglades Guest Services, LLC, an authorized concessioner of the NPS\": 24 rooms - \"eight two-bedroom suites that can accommodate up to six guests\", \"twelve one-bedroom suites suitable for up to four guests\" and \"four studios designed for two guests\" - with four ADA accessible rooms. The NPS release stated nightly rates from $159 (June-October) and $259 (November-May), plus tax."},{"name":"Flamingo Boat Tours","source":"https://developer.nps.gov/api/v1/thingstodo?parkCode=ever","accessed":"2026-10-03","si":["wildlife","family","senior","adventure"],"booking_route":"Everglades Guest Services (flamingoeverglades.com, 855-708-2207)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":4,"blurb":"Two 90-minute options from Flamingo Marina - the Backcountry Whitewater Bay tour and the Florida Bay tour; Adults $40, Children $20, per the NPS listing. Pets not permitted."},{"name":"Shark Valley loop and observation tower","source":"https://www.nps.gov/ever/planyourvisit/svdirections.htm","accessed":"2026-10-03","si":["hiking","wildlife","family","adventure"],"booking_route":"none needed to walk or ride your own bike; rentals from Shark Valley Tram Tours on site","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"\"Shark Valley Visitor Center provides the gateway to a panoramic 15-mile loop trail and observation tower\"; the tower is \"located halfway along the loop\" and \"offers panoramic views of the Everglades.\" Bicycle rentals on site ($25 per bike per the NPS listing). \"During peak visitor season...parking is extremely limited and usually fills by 10 am.\""},{"name":"Ten Thousand Islands Boat Tour","source":"https://www.nps.gov/ever/planyourvisit/gcdirections.htm","accessed":"2026-10-03","si":["wildlife","family","senior"],"booking_route":"operator website (evergladesnationalparkboattoursgulfcoast.com, which redirected to evergladers.com when fetched; no booking details read)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":6,"blurb":"From the Gulf Coast: Everglades National Park Adventures runs the Ten Thousand Islands boat tour on a 49-passenger pontoon; tours \"depart daily\" from 929 Dupont Street in Everglades City, about two miles north of the visitor center. The NPS lists it at 90 minutes."},{"name":"Flamingo Campground","source":"https://developer.nps.gov/api/v1/campgrounds?parkCode=ever","accessed":"2026-10-03","si":["adventure","group","family","motoring","wildlife"],"booking_route":"flamingoeverglades.com/camping/ or Everglades Guest Services 1-855-708-2207","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":7,"blurb":"\"one of two drive-in campgrounds accessible from the Homestead entrance of the park. It offers solar-heated showers, two dump stations, picnic tables, grills, and an amphitheater\"; 274 sites, 41 with electric hookups, 40 walk-to sites, 3 group sites; RV with electric $50 Mon-Thu / $60 Fri-Sun, tent or non-electric $33 / $38.50; maximum RV length 35 feet; open year-round."},{"name":"Flamingo glamping tents and houseboats","source":"https://www.nps.gov/ever/planyourvisit/eatingsleeping.htm","accessed":"2026-10-03","si":["glamping","adventure","wildlife","romance"],"booking_route":"Everglades Guest Services (flamingoeverglades.com, 855-708-2207)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":8,"blurb":"The NPS lists overnight stays at Flamingo \"in fully equipped houseboats, in a winter or summer glamping tent, or on the campgrounds\"; the concessioner, Everglades Guest Services, operates \"campsites, eco-tents and houseboats\"."},{"name":"Everglades Wilderness Waterway","source":"https://www.nps.gov/places/everglades-wilderness-waterway.htm","accessed":"2026-10-03","si":["adventure","wildlife","expedition"],"booking_route":"wilderness campsites reserved on Recreation.gov (90 days ahead)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"\"The 99-mile Wilderness Waterway attracts interest because it connects Flamingo and Everglades City\"; \"Most paddlers allow at least eight days to complete the trip\"; \"recommended for experienced paddlers only\", with a vehicle shuttle arranged in advance for one-way trips."},{"name":"Wilderness camping and chickees","source":"https://www.nps.gov/ever/planyourvisit/camping.htm","accessed":"2026-10-03","si":["adventure","wildlife","expedition"],"booking_route":"Recreation.gov; the NPS Gulf Coast page states a $21 administrative fee plus nightly per-person charges","commission_status":"none","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":10,"blurb":"\"ground sites, beach sites, and elevated camping platforms (''chickees'')\" reached by canoe, kayak, motorboat or on foot; \"A wilderness camping permit is required for all wilderness campsites\"; since January 2, 2023 \"all Marjory Stoneman Douglas Wilderness campsites will only be available for advanced reservations on Recreation.gov\", opening 90 days ahead."},{"name":"Gumbo Limbo Trail","source":"https://www.nps.gov/places/gumbo-limbo-trail.htm","accessed":"2026-10-03","si":["hiking","family","senior"],"booking_route":"none needed - covered by the park entrance pass","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":11,"blurb":"\"The Gumbo-Limbo trail is a self-guided, paved trail meandering through a shaded, jungle-like hardwood hammock\"; 0.4 miles (600 meters) round trip, wheelchair accessible, with accessible restrooms, a bottle-filling station and benches."},{"name":"Long Pine Key Campground","source":"https://developer.nps.gov/api/v1/campgrounds?parkCode=ever","accessed":"2026-10-03","si":["adventure","group","family","motoring"],"booking_route":"Everglades Guest Services 1-855-708-2207 or flamingoeverglades.com/camping/","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":12,"blurb":"108 sites for tents or RVs with no electrical hookups, plus a group site; $33 Mon-Thu and $38.50 Fri-Sun, group site $60; maximum RV length 35 feet; \"open seasonally November - April (closed May to October)\"; \"one of two frontcountry camping options run by the ''Flamingo Adventures'' concession.\""},{"name":"Ernest F. Coe Visitor Center","source":"https://developer.nps.gov/api/v1/visitorcenters?parkCode=ever","accessed":"2026-10-03","si":["family","senior"],"booking_route":"none needed - 40001 State Road 9336, Homestead; 305-242-7700","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":13,"blurb":"\"the visitor center closest to Homestead for Everglades National Park. It is open 365 days a year and offers educational displays, orientation films, and informational brochures\"; 9:00 AM - 5:00 PM daily, off Palm Drive (State Road 9336) from Florida City."},{"name":"Guy Bradley Visitor Center, Flamingo","source":"https://www.nps.gov/ever/planyourvisit/gbvc.htm","accessed":"2026-10-03","si":["wildlife","family"],"booking_route":"none needed - free visitor center","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":14,"blurb":"\"provides access to the southernmost region of Everglades National Park\" with rangers, displays, a gift shop and backcountry permits; \"roughly 38 miles (1 hour) south of the park main entrance\"; 8 am to 5 pm daily November 16 - April 30, closed Wednesday and Thursday in summer."},{"name":"Marjory Stoneman Douglas Visitor Center (Gulf Coast)","source":"https://developer.nps.gov/api/v1/visitorcenters?parkCode=ever","accessed":"2026-10-03","si":["adventure","wildlife"],"booking_route":"none needed - rangers on site or (786) 758-0635","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":15,"blurb":"\"open daily from 9am to 5pm. The site features a kayak launch, wildlife watching, and a picnic area\"; reached from I-75 exit 80, 20 miles south on State Road 29 to Everglades City. Park passes cannot be bought here - only at Shark Valley or Homestead."},{"name":"Eco Pond","source":"https://developer.nps.gov/api/v1/places?parkCode=ever","accessed":"2026-10-03","si":["wildlife","hiking"],"booking_route":"none needed - covered by the park entrance pass","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":16,"blurb":"\"Located on the road to the Flamingo Campground, Eco Pond has a ½ mile loop trail.\" The NPS lists birding at Flamingo among its featured activities."},{"name":"Bobcat Boardwalk Trail","source":"https://developer.nps.gov/api/v1/places?parkCode=ever","accessed":"2026-10-03","si":["hiking","family","senior"],"booking_route":"none needed - covered by the park entrance pass","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":17,"blurb":"At Shark Valley: \"A short accessible .2 miles trail that winds through a willowhead.\""},{"name":"Coot Bay Pond","source":"https://developer.nps.gov/api/v1/places?parkCode=ever","accessed":"2026-10-03","si":["adventure","wildlife"],"booking_route":"none needed - bring your own boat or rent at Flamingo Marina","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":18,"blurb":"\"This small pond opens up to Coot Bay, and is great for paddling and wildlife viewing.\""},{"name":"Flamingo Marina","source":"https://developer.nps.gov/api/v1/places?parkCode=ever","accessed":"2026-10-03","si":["adventure","sailing","wildlife"],"booking_route":"Everglades Guest Services (flamingoeverglades.com, 855-708-2207) for slips and rentals","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":19,"blurb":"\"The Flamingo Marina, open year-round, can accommodate boats with electric and water hookups\"; the Flamingo Fish Cleaning Station \"is located adjacent to public boat ramps and the marina store\". The NPS lists \"bicycle and boat rentals\" at Flamingo."},{"name":"Fishing in Everglades National Park","source":"https://www.nps.gov/ever/faqs.htm","accessed":"2026-10-03","si":["adventure","wildlife"],"booking_route":"none needed in the park - a Florida fishing licence is required","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":20,"blurb":"\"A Florida fishing license is required, unless you are under 16 years of age or you are a Florida resident over the age of 65\"; freshwater rules apply north of Nine Mile Pond and saltwater rules south of it."},{"name":"Flamingo Restaurant","source":"https://www.nps.gov/ever/planyourvisit/eatingsleeping.htm","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in at Flamingo (no reservation method read)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":21,"blurb":"\"The Flamingo Restaurant, adjacent to the Flamingo Lodge, is open daily for breakfast, lunch, and dinner\"; the NPS release describes \"traditional South Florida fare while enjoying views of nearby Florida Bay\" and a full-service bar."},{"name":"Coopertown Airboats","source":"https://www.coopertownairboats.com/","accessed":"2026-10-03","si":["wildlife","family","adventure"],"booking_route":"own website (\"Buy Your Tickets\") or (305) 226-6048","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":22,"blurb":"One of \"three authorized airboat businesses inside Everglades National Park\" on the Tamiami Trail, per the NPS. Its own page: airboat rides covering \"approximately 5 miles of this unique environment\", standard and private tours, gift shop; 22700 Southwest 8th Street, Miami, FL 33194; (305) 226-6048."},{"name":"Everglades Alligator Farm","source":"https://www.everglades.com/","accessed":"2026-10-03","si":["wildlife","family"],"booking_route":"FareHarbor (fareharbor.com/embeds/book/everglades) from the own website, or phone","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":23,"blurb":"\"Airboat Rides & Alligator Shows\" - airboat rides with 360° spins, 2,000+ alligators, animal encounters; family-owned since 1992; 40351 SW 192nd Ave, Homestead, FL 33034; daily 9:00 AM - 5:30 PM; +1 (305) 247-2628."},{"name":"Everglades Adventures Kayak & Eco Tours","source":"https://www.evergladesadventures.com/","accessed":"2026-10-03","si":["adventure","wildlife","expedition","family"],"booking_route":"FareHarbor from the own website","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":24,"blurb":"605 Buckner Ave N, Everglades City: guided kayak tours \"with the guidance and knowledge of a trained naturalist\" (from $89), guided bike tours (from $79), kayak and canoe rentals (from $29), Wilderness Waterway trips of 5-10 days (from $725) and kayak-camping combos with meals and gear; daily 8:00 am - 9:00 pm; 239-294-8487."},{"name":"Ivey House","source":"https://www.iveyhouse.com/","accessed":"2026-10-03","si":["adventure","wildlife","family"],"booking_route":"own website or 239-695-3299","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":25,"blurb":"605 Buckner Ave N, Everglades City: \"Enjoy peaceful accommodations by night and exciting adventures by day!\" - king or queen rooms beside \"a screened-in courtyard and pool\"; arranges airboat tours, seasonal kayak tours \"that leave right from the hotel\" and fishing charters; 239-695-3299."},{"name":"Fairfield Inn & Suites Homestead Florida City","source":"https://www.hotelplanner.com/Attractions/7055-Things-to-do-in-Florida-City-FL","accessed":"2026-10-03","si":["family","senior","wildlife"],"booking_route":"marriott.com (brand booking; not fetched - HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":26,"blurb":"Marriott''s Fairfield Inn & Suites at \"60 SW 352nd St., Florida City, FL 33034\" - Florida City is where Palm Drive (State Road 9336) leads to the park''s main entrance, per the NPS. Marriott''s own page refused the fetch (HTTP 403), so nothing else about the property is stated here."},{"name":"TownePlace Suites by Marriott Miami Homestead","source":"https://www.hotelplanner.com/Attractions/7055-Things-to-do-in-Florida-City-FL","accessed":"2026-10-03","si":["family","senior"],"booking_route":"marriott.com (brand booking; not fetched - HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":27,"blurb":"\"935 Northeast 30th St., Homestead, FL 33033 ~9.10 miles northeast\" of Florida City, as the listing states. Marriott''s own page refused the fetch (HTTP 403), so nothing else about the property is stated here."},{"name":"Hampton Inn & Suites Homestead Miami South","source":"https://www.hotelplanner.com/Attractions/7055-Things-to-do-in-Florida-City-FL","accessed":"2026-10-03","si":["family","senior"],"booking_route":"hilton.com (brand booking; not fetched - HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":28,"blurb":"Hilton''s Hampton Inn & Suites at \"2855 NE 9th St., Homestead, FL 33033 ~9.02 miles northeast\" of Florida City, as the listing states. Hilton''s own page refused the fetch (HTTP 403), so nothing else about the property is stated here."},{"name":"Holiday Inn Express & Suites Florida City","source":"https://www.hotelplanner.com/Attractions/7055-Things-to-do-in-Florida-City-FL","accessed":"2026-10-03","si":["family","senior"],"booking_route":"ihg.com (brand booking; not fetched - HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":29,"blurb":"IHG''s Holiday Inn Express & Suites at \"35200 South Dixie Highway, Florida City, FL 33034\", as the listing states. IHG''s own page refused the fetch (HTTP 403), so nothing else about the property is stated here."},{"name":"Baker''s Cay Resort Key Largo, Curio Collection by Hilton","source":"https://www.hotelplanner.com/Attractions/7055-Things-to-do-in-Florida-City-FL","accessed":"2026-10-03","si":["romance","tropical","family"],"booking_route":"hilton.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":30,"blurb":"Hilton''s Curio Collection resort at \"97000 Overseas Highway, Key Largo, FL\", listed among hotels near Florida City - the top-tier brand option within reach of the Homestead entrance. Hilton''s own page was not fetched (hilton.com returned HTTP 403 for the Homestead property), so nothing else about it is stated here."},{"name":"Everglades Isle","source":"https://www.evergladesisle.com/","accessed":"2026-10-03","si":["motoring","sailing"],"booking_route":"Staylist (booking.staylist.app/evergladesisle) or (239) 695-2600","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":31,"blurb":"\"A luxury motorcoach resort and marina nestled in beautiful Everglades City on Florida''s Gulf Coast\": 59 motorcoach lots, 2 luxury villas and 74 boat slips; pool, spa, fitness center, clubhouse, pickleball and a full-service bar; \"All motorcoaches must be Class A or Super C, 36''+ in length, and twelve years old or newer.\" 803 N Collier Ave; (239) 695-2600."},{"name":"Chokoloskee Island Resort","source":"https://www.covecommunities.com/rv-resorts/florida/chokoloskee-island-resort/","accessed":"2026-10-03","si":["motoring","adventure","family"],"booking_route":"bookings.covecommunities.com or reservations 855-964-2683","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":32,"blurb":"1150 Hamilton Lane, Chokoloskee: a waterfront \"All Age RV Park\" with 40+ RV sites with water and power, trailer and cottage rentals, a \"Marina\" and \"Boat Launch Ramp\", docks, a tiki gathering spot and boat and kayak rentals; front desk 239-695-2414."},{"name":"Miami Everglades RV Resort","source":"https://www.rvonthego.com/florida/miami-everglades/","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"own website reservations or 877-570-2267","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":33,"blurb":"20675 SW 162nd Ave, Miami: \"Everglades National Park is less than 10 miles away\"; clubhouse, pool (\"currently closed until further notice\"), shuffleboard, mini golf, dog park, rental campers; \"Open Year Round\"; 305-233-5300."},{"name":"Larry & Penny Thompson Park Campground","source":"https://www.miamidade.gov/parks/larry-penny.asp","accessed":"2026-10-03","si":["family","motoring"],"booking_route":"Miami-Dade ParkLink online or 305-755-7800","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":34,"blurb":"Miami-Dade County park: \"The campground consists of 240 separate campsites for recreational vehicles, each with electrical, sewer and water hookups\"; tent sites \"Daily rate: $25 + tax\", check-in 9 a.m. to 5 p.m."},{"name":"Trail Lakes Campground","source":"https://evergladescamping.net/","accessed":"2026-10-03","si":["glamping","motoring","family","wildlife"],"booking_route":"own website (\"click here to go camping\") or 1-800-504-6554","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":35,"blurb":"40904 Tamiami Trail, Ochopee, in Big Cypress National Preserve: \"chickee huts\" for glamping - \"Native American built chickee cottages\" - plus air-conditioned rustic cabins, RV sites to 50 feet with 30/50 amp and water, primitive tent camping, and swamp buggy and airboat tours; 1-800-504-6554. The Dyrt lists it \"7mi from Everglades City\"."},{"name":"Robert Is Here","source":"https://robertishere.com/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in","commission_status":"none","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat","shop"],"draw_rank":36,"blurb":"\"The World''s Best Fruit Stand\", \"Since 1959\": exotic and tropical fruit, \"out-of-this-world milkshakes\" made with hand-cut fruit, a petting zoo and picnic areas; 19200 SW 344th St, Homestead - on the road to the park entrance; \"Open everyday from 9am-6pm\", closed Thanksgiving and Christmas Day; (305) 246-1592."},{"name":"Schnebly Redland''s Winery","source":"https://www.schneblywinery.com/","accessed":"2026-10-03","si":["wine","culinary","romance"],"booking_route":"OpenTable or (305) 242-1224","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat","activities"],"draw_rank":37,"blurb":"\"the southernmost winery in the United States\", making \"exotic tropical fruit wines\", with Miami Brewing Company and a farm-to-table restaurant; 30205 SW 217th Ave, Homestead; wine tasting $25, tour $16, tour and tasting $41; (305) 242-1224."},{"name":"Shiver''s BBQ","source":"https://www.shiversbbq.com/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in or (305) 248-2272","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":38,"blurb":"\"authentic hickory smoked barbecue\" in Homestead since 1950; 28001 South Dixie Highway, Homestead, FL 33033; (305) 248-2272."},{"name":"Triad Seafood Market & Cafe","source":"https://www.triadseafoodmarketcafe.com/","accessed":"2026-10-03","si":["culinary"],"booking_route":"walk-in; call ahead 239-695-2662","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat","shop"],"draw_rank":39,"blurb":"Restaurant and seafood market at 401 W School Dr, Everglades City: \"All-You-Can-Eat Stone Crab Season Begins October 15\"; seasonal from October through spring - \"Please call ahead for current hours and to confirm stone crab availability\"; 239-695-2662."},{"name":"HavAnnA Cafe of the Everglades","source":"https://www.florida-backroads-travel.com/havana-cafe-of-the-everglades.html","accessed":"2026-10-03","si":["culinary"],"booking_route":"walk-in; 239-695-2214","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":40,"blurb":"A \"casual family owned-restaurant that many visitors to Chokoloskee make a special point of enjoying for breakfast, lunch, or early dinner\" - seafood with Latin influences, blackened grouper, stone crab and Cuban sandwiches; 191 Smallwood Drive, Chokoloskee; \"open Wednesday-Sunday from 7am to 4pm\"; 239-695-2214. Its own site (havanacafeoftheeverglades.com) returned 404."}],"faq":[{"q":"How much is Everglades National Park?","a":"The NPS fees page lists \"Private Vehicle: $35.00\" (\"Good for 7 consecutive days\"), \"Motorcycle: $30.00\", \"Per Person: $20.00\" and \"Annual Entrance - Park: $70.00\". Only \"Digital passes or credit/debit cards\" are accepted, at the Homestead and Shark Valley entrance stations or online.","source":"https://www.nps.gov/ever/planyourvisit/fees.htm","accessed":"2026-10-03"},{"q":"Can you camp in Everglades National Park?","a":"Yes. Flamingo Campground (274 sites, 41 with electric hookups, open year-round) and Long Pine Key Campground (108 sites, \"open seasonally November - April\") are booked through Everglades Guest Services at 1-855-708-2207. Wilderness ground sites, beach sites and chickees need a permit, and \"all Marjory Stoneman Douglas Wilderness campsites will only be available for advanced reservations on Recreation.gov.\"","source":"https://developer.nps.gov/api/v1/campgrounds?parkCode=ever","accessed":"2026-10-03"},{"q":"What is the best time to visit Everglades National Park?","a":"The NPS describes the dry season, \"from about December to mid-May, with temperatures ranging from the low 50s to upper 70s... and low humidity\", against a wet season \"from about mid-May to November\" with temperatures \"into the low 90s\". December through April is peak visitation because \"the warm winters...attract the largest variety of wading birds.\"","source":"https://www.nps.gov/ever/planyourvisit/weather.htm","accessed":"2026-10-03"},{"q":"Can you drive through Everglades National Park?","a":"Not end to end. The park has three entrances - the main Homestead entrance, Shark Valley on U.S. 41 and the Gulf Coast in Everglades City - and \"these entrances do not interconnect within the park.\" From Homestead, the main park road leads to Royal Palm and Flamingo.","source":"https://www.nps.gov/ever/faqs.htm","accessed":"2026-10-03"},{"q":"Are there airboat tours in Everglades National Park?","a":"Yes: \"There are three authorized airboat businesses inside Everglades National Park. All three are located along the Tamiami Trail (Coopertown, Everglades Safari Park, and Gator Park).\"","source":"https://www.nps.gov/ever/faqs.htm","accessed":"2026-10-03"},{"q":"Can you swim in Everglades National Park?","a":"Largely no: \"Swimming/Snorkeling is prohibited in all canals, ponds, freshwater lakes, marked channels, and boat basins inside the park.\"","source":"https://www.nps.gov/ever/faqs.htm","accessed":"2026-10-03"},{"q":"Can you fish in Everglades National Park?","a":"Yes, with a licence: \"A Florida fishing license is required, unless you are under 16 years of age or you are a Florida resident over the age of 65.\" Freshwater rules apply north of Nine Mile Pond and saltwater rules south of it.","source":"https://www.nps.gov/ever/faqs.htm","accessed":"2026-10-03"},{"q":"Where can you stay in Everglades National Park?","a":"Only at Flamingo: the NPS lists stays \"in Flamingo Lodge, in fully equipped houseboats, in a winter or summer glamping tent, or on the campgrounds\", plus Long Pine Key campground near the Homestead entrance and \"numerous backcountry sites for wilderness camping\". Outside the park, the NPS points to Homestead, Florida City, Miami, Everglades City and Chokoloskee.","source":"https://www.nps.gov/ever/planyourvisit/eatingsleeping.htm","accessed":"2026-10-03"},{"q":"When was Everglades National Park established?","a":"\"Established in 1947 as the first national park created for its biodiversity, Everglades National Park protects 1.5 million acres of wetland, forest, and marine habitats\".","source":"https://developer.nps.gov/api/v1/parks?parkCode=ever","accessed":"2026-10-03"},{"q":"Is Everglades National Park open?","a":"\"Everglades National Park is open 7 days a week, 24 hours a day.\" Staffed entrance hours are 8:00 a.m. to 4:30 p.m. daily, and the Ernest F. Coe, Shark Valley and Gulf Coast visitor centers open 9:00 AM - 5:00 PM.","source":"https://developer.nps.gov/api/v1/parks?parkCode=ever","accessed":"2026-10-03"}],"seo":{"meta_title":"Everglades National Park: Anhinga Trail, Shark Valley & Flamingo | TravelWell","meta_description":"Three entrances that do not connect, the Anhinga Trail, Shark Valley''s 15-mile loop, Flamingo Lodge and campgrounds, airboats and where to stay nearby.","slug":"everglades-national-park-florida","primary_keyword":"Everglades National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Everglades National Park Anhinga Trail"}}'::jsonb, 42),
  ('biscayne-florida', '12A', 'Biscayne National Park', 'United States', 'Coral reefs, island keys and shipwrecks off Miami', 'future', 'verified', 'mountainValley', 'Florida - Atlantic & the Keys', '{"ocean","diveglobal","sailing","tropical","wildlife","parks"}', '{"tropical","coastal","serene","adventurous"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Biscayne National Park Institute boat, snorkel and paddle tours","source":"https://www.biscaynenationalparkinstitute.org/","accessed":"2026-10-03","si":["ocean","group","diveglobal","sailing","wildlife","family"],"booking_route":"FareHarbor on the Institute''s own site, 786-335-3644, or the park store","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":1,"blurb":"\"a non-profit where your purchase directly benefits the park\"; trips include the \"Boca Chita Key Heritage Cruise from Coconut Grove\", \"Snorkel Experience\", \"Jones Lagoon Eco-Paddle\", \"Kayak the Seagrasses of Stiltsville\" and \"Sail, Paddle and Snorkel\", from the Dante Fascell Visitor Center, Dinner Key Marina and the Deering Estate; most standard trips $65-$219. The NPS: \"Advance reservations are advised\", 786-335-3644."},{"name":"Boca Chita Key","source":"https://www.nps.gov/bisc/planyourvisit/camping.htm","accessed":"2026-10-03","si":["tropical","sailing","romance","ocean"],"booking_route":"first-come, first-served; $25 day-use docking Fri-Mon and federal holidays, $60 a night camping and docking","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":2,"blurb":"\"the park''s most popular island\": \"beautiful waterfront views, a grassy camping area, picnic tables and grills. Toilets are available, but there are no showers, sinks or drinking water.\" Harbor entrance about four feet at low tide; pets prohibited, \"including on boats docked in the harbor\"."},{"name":"Maritime Heritage Trail","source":"https://www.nps.gov/bisc/learn/historyculture/maritime-heritage-trail.htm","accessed":"2026-10-03","si":["diveglobal","ocean","culture"],"booking_route":"none needed - free; reached by private boat or an Institute snorkel/dive trip","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"\"Six wrecks, spanning nearly a century and a wide variety of sizes and vessel types\" - Arratoon Apcar (1878), Erl King (1891), Alicia (1905), Lugano (1913), Mandalay (1966) and an unidentified 19th-century wooden sailing vessel - plus the Fowey Rocks Lighthouse; \"Access to the sites on the trail is by boat only.\" Three wrecks suit scuba."},{"name":"Dante Fascell Visitor Center","source":"https://www.nps.gov/bisc/planyourvisit/hours.htm","accessed":"2026-10-03","si":["family","senior","ocean"],"booking_route":"none needed - free entry","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"\"9700 SW 328th Street, Sir Lancelot Jones Way, Homestead, FL 33033\", at the end of SW 328th Street; \"open 7 days a week from 9 AM-5 PM\". Only selected America the Beautiful passes are sold here - \"4th grade, Access, and U.S. military passes\". Pets are not allowed inside."},{"name":"Elliott Key","source":"https://www.nps.gov/bisc/planyourvisit/elliottkey.htm","accessed":"2026-10-03","si":["tropical","sailing","hiking","family"],"booking_route":"first-come, first-served; $25 day-use docking Fri-Mon and federal holidays, $60 a night camping and docking","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":5,"blurb":"\"The largest island in the park\", once \"a thriving community of pioneers engaged in pineapple farming, sponging, wrecking\"; campground with restrooms, \"cold water showers\", drinking water, tables and grills; \"There are 33 boat slips in the marina\", about 2½ feet deep at low tide. Leashed pets allowed in developed areas."},{"name":"Mandalay shipwreck","source":"https://www.nps.gov/bisc/learn/historyculture/maritime-heritage-trail.htm","accessed":"2026-10-03","si":["diveglobal","ocean","family"],"booking_route":"none needed - free; by private boat or an Institute snorkel trip","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":6,"blurb":"The 1966 wreck on the Maritime Heritage Trail that the NPS names as particularly accessible to snorkellers; \"Access to the sites on the trail is by boat only.\""},{"name":"Stiltsville","source":"https://www.nps.gov/bisc/learn/historyculture/stiltsville.htm","accessed":"2026-10-03","si":["culture","ocean","sailing"],"booking_route":"seen from the water; entry to the structures by Stiltsville Trust permit only","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"\"Seeming to float above Biscayne Bay''s shallow seagrass beds, Stiltsville has a colorful history that dates back to the 1930s\"; 27 structures in 1960, \"only seven buildings standing\" after Hurricane Andrew in 1992. \"Public access to the structures themselves is by permit only\" (Stiltsville Trust)."},{"name":"Fowey Rocks Lighthouse","source":"https://www.nps.gov/bisc/learn/historyculture/maritime-heritage-trail.htm","accessed":"2026-10-03","si":["ocean","diveglobal","culture"],"booking_route":"none needed - by boat; the lighthouse itself is closed to the public","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":8,"blurb":"\"The newest addition to the trail is the Fowey Rocks Lighthouse\", built 1878; \"not open to the public\", but \"snorkeling is great around the base.\""},{"name":"Jones Lagoon","source":"https://www.nps.gov/bisc/planyourvisit/guidedtours.htm","accessed":"2026-10-03","si":["wildlife","adventure","ocean"],"booking_route":"Biscayne National Park Institute (FareHarbor), 786-335-3644","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":9,"blurb":"Named by the NPS among the concession tours - \"exploring the seldom seen wonders of Jones Lagoon\" - and run by the Institute as the \"Jones Lagoon Eco-Paddle\". \"Trips may be booked by using the link below, by calling 786-335-3644 or by stopping at the park store.\""},{"name":"Spite Highway, Elliott Key","source":"https://www.nps.gov/bisc/planyourvisit/elliottkey.htm","accessed":"2026-10-03","si":["hiking","wildlife"],"booking_route":"none needed - free trail; island reached by private boat","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"A trail \"approximately six miles down the center of the island\" through maritime forest; Elliott Key also has \"a mile-long loop trail\" that \"starts near the campground\"."},{"name":"Convoy Point grounds and canoe/kayak launch","source":"https://www.nps.gov/bisc/planyourvisit/hours.htm","accessed":"2026-10-03","si":["family","adventure","senior"],"booking_route":"none needed - free; bring your own paddle craft","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":11,"blurb":"The mainland grounds beside the visitor center and the canoe/kayak launch are \"open 7 days a week from 7 AM-5:30 PM\"; leashed pets are allowed on \"The grounds at Convoy Point\"."},{"name":"Fishing and lobstering in Biscayne National Park","source":"https://www.nps.gov/bisc/planyourvisit/fishing.htm","accessed":"2026-10-03","si":["ocean","adventure"],"booking_route":"none needed in the park - a Florida fishing licence (state) is required","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":12,"blurb":"\"With limited exceptions, a valid Florida fishing license is required to fish in the park. Children under 16 years of age do not require a license.\" \"The taking of lobster is prohibited in the Biscayne Bay/Card Sound Lobster Sanctuary\", and in five Coral Reef Protection Areas marked with yellow buoys; lionfish may be speared without a licence using lionfish-specific devices."},{"name":"Adams Key","source":"https://www.nps.gov/bisc/planyourvisit/hours.htm","accessed":"2026-10-03","si":["ocean","sailing"],"booking_route":"none needed - by private boat","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":13,"blurb":"A day-use island \"Open 9 AM until official sunset daily\", reached across the navigable waters, which are \"Open 24 hours a day\"."},{"name":"Manatee watching","source":"https://www.nps.gov/bisc/faqs.htm","accessed":"2026-10-03","si":["wildlife","family"],"booking_route":"none needed - ask a ranger at the Dante Fascell Visitor Center","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":14,"blurb":"Asked whether manatees can be seen: \"yes, ask a park ranger about recent sightings. Manatees are more common during the colder months.\""},{"name":"John Pennekamp Coral Reef State Park","source":"https://www.pennekamppark.com/","accessed":"2026-10-03","si":["diveglobal","ocean","family","tropical"],"booking_route":"Peek online booking from the concession site, or (305) 451-6300","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":15,"blurb":"Key Largo, MM 102.5: \"The first undersea park in the United States\", about 70 nautical square miles; a 65-foot glass-bottom catamaran for up to 130 passengers, 2.5-hour snorkel tours with about 1.5 hours in the water, scuba trips, and kayak/canoe rentals on \"50 miles of natural mangrove wilderness trails\". (305) 451-6300. The state-park page refused the fetch (HTTP 403); this is the concession''s own site."},{"name":"Rainbow Reef Dive Center","source":"http://www.rainbowreef.com/","accessed":"2026-10-03","si":["diveglobal","ocean"],"booking_route":"own website booking or phone","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":16,"blurb":"Key Largo: \"Dive & snorkel trips, gear rental sales and service, all levels of dive training, hotel accommodations, and dive/hotel packages\"; reef, wreck, drift and night dives at 18-120 feet; a PADI 5 Star Instructor/Career Development Center. 1-800-457-4354 / 305-451-7171."},{"name":"Homestead Bayfront Park","source":"https://www.miamidade.gov/parks/homestead-bayfront.asp","accessed":"2026-10-03","si":["family","ocean","sailing"],"booking_route":"pay at the gate; marina services through the park office","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities","move"],"draw_rank":17,"blurb":"Miami-Dade County park \"adjacent to Biscayne National Park\": the \"Atoll Pool\" swim area (\"Sunrise to sunset, seven days a week\"), a beach, the Herbert Hoover Marina with \"boat-launching ramps\" and fuel, and La Playa Grill Seafood Bar. Vehicle entry \"$5 weekdays; $7 weekends and holidays\"; boat ramps open \"six a.m. to ten p.m.\""},{"name":"Larry & Penny Thompson Park campground","source":"https://www.miamiandbeaches.com/l/outdoor-experiences/larry-and-penny-thompson-park/2970","accessed":"2026-10-03","si":["family","motoring"],"booking_route":"phone the park, (305) 232-1049; tent sites first-come, first-served","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":18,"blurb":"12451 SW 184th St., Miami, beside Zoo Miami: a 270-acre county park with \"240 campsites for recreational vehicles as well as an individual tent area\", \"four large restroom and laundry facilities with hot showers, water and electrical hook-ups for all RVs and complimentary WiFi\", and a freshwater swimming lake. Tent sites first-come, first-served. (305) 232-1049. Sourced to Greater Miami''s tourism board."},{"name":"Goldcoaster RV Resort","source":"https://www.campspot.com/park/goldcoaster-rv-resort","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"Campspot","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"not-established","commission_pct_low":3,"commission_pct_high":3,"commission_basis":"published","wells":["stay"],"draw_rank":19,"blurb":"34850 S.W. 187th Ave., Homestead: \"Surrounded by Everglades National Park and Biscayne National Park\"; pool, hot tub/sauna, arcade, playground, pavilion, shuffleboard, laundry and internet; \"100% pet-friendly\", a \"resort-style gated community\" where about 90% of trailers are permanently stationed."},{"name":"Gate to the Keys","source":"https://www.hipcamp.com/en-GB/land/florida-gate-to-the-keys-mxvh0keq","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"Hipcamp","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":20,"blurb":"Homestead: three RV-only sites (Rabbit, Rooster, Peacock) with electric and water hookups among \"Banana, Lychee, Mangos, avocado\" trees; campfires allowed, pets welcome; about 2 miles from Robert Is Here; \"Within a 30-minute drive from the Everglades Ernest F. Coe Visitor Center\" (listing''s own wording). Hipcamp listing, not the host''s own site."},{"name":"Sun Outdoors Key Largo","source":"https://www.hipcamp.com/en-US/land/florida-sun-outdoors-key-largo-v1qh28lj","accessed":"2026-10-03","si":["tropical","motoring","ocean"],"booking_route":"Hipcamp","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":21,"blurb":"97680 Overseas Hwy, MM 97.5, Key Largo: 24 full-hookup RV sites plus 20 motel rooms, efficiencies and cottages; boat launch, docks, private beach, \"free kayaks\", tiki area and BBQ. Hipcamp lists it 27 miles from Homestead. Hipcamp listing, not the operator''s own site."},{"name":"Tropical Farm Stay Retreat - Cozy Tiny Barn","source":"https://www.hipcamp.com/en-US/land/florida-tropical-farm-stay-retreat-cozy-tiny-barn-xryh5jl1","accessed":"2026-10-03","si":["glamping","family","culinary"],"booking_route":"Hipcamp","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":22,"blurb":"Homestead, on \"a peaceful fruit farm in the heart of the Redlands\": a converted horse barn tiny home for 4 with \"full private bathroom with a walk-in shower\", kitchen, Wi-Fi and fenced patio, among tropical fruit trees, chickens and a mini horse; \"Within a 30-minute drive from the Dante Fascell Visitor Center\" (listing''s own wording). Listed on Hipcamp''s Homestead glamping page."},{"name":"Baker''s Cay Resort Key Largo, Curio Collection by Hilton","source":"https://www.bakerscay.com/","accessed":"2026-10-03","si":["tropical","romance","ocean","family"],"booking_route":"own website (Hilton booking) or phone","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":23,"blurb":"97000 Overseas Highway, Key Largo: 15 acres of a former pineapple plantation overlooking Florida Bay; five dining venues (Calusa, Dry Rocks, The Pool Bar, Tiki Bar, Dock to Dish), Scupper''s watersports rentals, pools, and day resort passes for non-guests. +1-305-852-5553."},{"name":"Courtyard by Marriott Miami Homestead","source":"https://www.priceline.com/hotel-deals/c3000003234/US/Florida/Homestead-Hotels.html","accessed":"2026-10-03","si":["family","senior"],"booking_route":"marriott.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"published","w