insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('dry-tortugas-florida', '12A', 'Dry Tortugas National Park', 'United States', 'Fort Jefferson, coral reefs and sooty terns', 'future', 'verified', 'mountainValley', 'Florida - Atlantic & the Keys', '{"culture","wildlife","tropical","ocean","adventure","parks"}', '{"remote","historic","tropical","secluded"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Fort Jefferson","source":"https://www.nps.gov/drto/learn/historyculture/index.htm","accessed":"2026-10-03","si":["culture","family","senior"],"booking_route":"none needed inside the park - entry with the $15 park entrance fee (included in ferry tickets)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"\"Fort Jefferson, the largest all-masonry fort in the United States, was built between 1846 and 1875 to protect the nation''s gateway to the Gulf of America\"; \"Distinguishing features include decorative brickwork and 2,000 arches.\" Never finished nor fully armed; a Civil War prison whose \"most famous prisoner was Dr. Samuel Mudd, the physician who set the broken leg of John Wilkes Booth.\" Open sunrise to sunset."},{"name":"Garden Key swim beaches and snorkeling","source":"https://www.nps.gov/drto/planyourvisit/swimming-beaches.htm","accessed":"2026-10-03","si":["tropical","ocean","family","wildlife"],"booking_route":"none needed - free with park entry; the ferry and seaplane lend snorkel gear","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"\"The swim areas on Garden Key are accessible via North, South, and East Beach. These beaches offer gradual slope and easy entry and are ideal for beginner swimmers and snorkelers.\" The park sits \"at the southwest corner of the Florida Keys reef system, the third largest in the world\". \"No lifeguard on duty.\""},{"name":"Yankee Freedom ferry","source":"http://web.archive.org/web/20260818080409/https://www.drytortugas.com/","accessed":"2026-10-03","si":["ocean","family","culture","tropical"],"booking_route":"own website (drytortugas.com) or 800-634-0939","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["move","activities"],"draw_rank":3,"blurb":"\"Yankee Freedom III, LLC is authorized by the NPS and the Department of the Interior to serve the public at Dry Tortugas National Park\"; \"the Official Dry Tortugas National Park Ferry\", a high-speed catamaran from 100 Grinnell Street, Key West. Day itinerary: depart 8:00 am, arrive Fort Jefferson 10:15 am, return 5:15 pm; breakfast and lunch, snorkel gear, a narrated fort tour and the park entrance fee included. Read from a Wayback snapshot of 2026-08-18 - the live site returned HTTP 403."},{"name":"Key West Seaplane Adventures","source":"https://keywestseaplanecharters.com/rates/","accessed":"2026-10-03","si":["ocean","privatejet","wildlife","romance"],"booking_route":"own website (\"This is the only direct booking website\") or 305-293-9300","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["fly","activities"],"draw_rank":4,"blurb":"\"We are the only Seaplane Service permitted in Dry Tortugas National Park.\" Half-day trip \"just under 4 hours long, providing at least 2 1/2 hours of island time\", full day at least 6 1/2 hours; \"Travel time is approximately 40 minutes each way\". Adult fares read: $527 half day, $910 full day, plus the $15 NPS entrance fee. 3471 South Roosevelt Blvd., Key West; 305-293-9300."},{"name":"Garden Key Campground","source":"https://www.nps.gov/drto/planyourvisit/camping.htm","accessed":"2026-10-03","si":["adventure","tropical","wildlife"],"booking_route":"first come, first served on arrival; fees paid via Recreation.gov Scan & Pay; group site by emailed application","commission_status":"none","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":5,"blurb":"Primitive campground a short walk from the dock: eight regular sites for up to six people (first come, first served, \"All campers, once they arrive, will be guaranteed a place to camp\") plus a group site for 10-20 by reservation; $15 a night per site, $30 for the group site. Composting toilets, no showers, no water; ferry campers limited to 60 lbs of gear and no gas canisters."},{"name":"Loggerhead Key and Little Africa","source":"https://www.nps.gov/drto/planyourvisit/loggerhead-key.htm","accessed":"2026-10-03","si":["tropical","ocean","wildlife","adventure"],"booking_route":"none needed - private boat, kayak or a permitted charter; no public transport to the island","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":6,"blurb":"\"The largest island in the Dry Tortugas, Loggerhead Key is a site of shipwrecks, a significant lighthouse installation, and where the historic Carnegie Laboratory for Marine Ecology once stood.\" Three miles from Garden Key, day use only, reached by private vessel or kayak; its northwest swim area holds \"a remarkable coral formation aptly named Little Africa.\""},{"name":"Bush Key sooty tern colony","source":"https://www.nps.gov/drto/planyourvisit/bush-key.htm","accessed":"2026-10-03","si":["wildlife","hiking"],"booking_route":"none needed - on foot by land bridge when present, otherwise by kayak or canoe","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"16 acres; \"Bush Key closes every year around February to September, when up to 80,000 sooty terns and 4,500 brown noddies make nests and raise their young on the island. This is the only significant breeding colonies of sooty terns and brown noddies in the United States.\" When open, a 1-mile round-trip shoreline trail, sunrise to sunset."},{"name":"Birding and sea turtles","source":"https://www.nps.gov/drto/planyourvisit/wildlife-viewing.htm","accessed":"2026-10-03","si":["wildlife","senior","ocean"],"booking_route":"none needed - free with park entry; NPS-permitted birding tours listed separately","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":8,"blurb":"\"Nearly 300 hundred species of birds have been spotted in the Dry Tortugas. Some species, like the magnificent frigatebird and sooty tern, nesting nowhere else in the continental United States\"; green and loggerhead turtles nest here, one of \"5 different sea turtles commonly found in the park\". \"Spring migration is the preferred season.\""},{"name":"Windjammer Wreck (Avanti)","source":"https://www.nps.gov/drto/learn/historyculture/windjammer.htm","accessed":"2026-10-03","si":["diveglobal","culture","ocean"],"booking_route":"none needed - private boat on a day-use mooring buoy, or an NPS-permitted dive charter","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"On Loggerhead Reef, \"identified as the Norwegian Avanti, which sank January 22, 1907 while en route to Montevideo, Uruguay from Pensacola\"; an iron-hulled three-masted ship of 1875, 261.4 feet long. Two wreckage fields, each \"roughly 110 feet in length\". The Loggerhead Key page places it \"a mile southwest of Loggerhead Key\"."},{"name":"Paddling from Garden Key","source":"https://www.nps.gov/drto/planyourvisit/paddlesports.htm","accessed":"2026-10-03","si":["adventure","ocean","wildlife"],"booking_route":"none needed - bring your own kayak on the ferry by advance arrangement","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"\"Bush and Long Key are the closest to Garden Key and home to thousands of nesting birds in the spring. A trip around these two islands generally takes a few hours.\" Loggerhead Key \"can take several hours to paddle round trip\" and \"involves crossing deep, open water with very strong currents.\" PFD, signalling device and portable VHF radio required; launch from the dinghy beach."},{"name":"Fishing in Dry Tortugas National Park","source":"https://www.nps.gov/drto/planyourvisit/fishing.htm","accessed":"2026-10-03","si":["ocean","adventure"],"booking_route":"none needed in the park - a Florida saltwater licence is required (FWC)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":11,"blurb":"\"A Florida Saltwater fishing license is required, unless you are under the age of 16 or a Florida resident over the age of 65.\" Circle hooks only; fishing prohibited in the Research Natural Area (46% of the park); \"Neither spearfishing nor lobstering is allowed in the Park.\" Shore spots include the main dock when the Yankee Freedom is not present and the seaplane beach when the seaplane is away."},{"name":"Night sky over Garden Key","source":"https://www.nps.gov/drto/planyourvisit/garden-key.htm","accessed":"2026-10-03","si":["romance","adventure","family"],"booking_route":"none needed - campers and overnight boaters only","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":12,"blurb":"\"With minimal light pollution, Garden Key offers incredible views of the Milky Way and star-filled skies.\" The NPS camping page lists \"amazing star gazing\" among the reasons to stay overnight."},{"name":"Garden Key Visitor Center","source":"https://www.nps.gov/drto/planyourvisit/hours.htm","accessed":"2026-10-03","si":["family","culture","senior"],"booking_route":"none needed - inside Fort Jefferson''s island","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":13,"blurb":"\"Garden Key Visitor Center is open every day from 8:30 AM - 4:30 PM.\" Garden Key is \"home to park headquarters, visitor center, campgrounds and great swimming and snorkeling areas\", about 14 acres."},{"name":"Private boating and overnight anchoring","source":"https://www.nps.gov/drto/faqs.htm","accessed":"2026-10-03","si":["sailing","yacht","ocean"],"booking_route":"digital entrance pass on Recreation.gov; boat permit filed at Garden Key","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":14,"blurb":"\"Overnight anchoring is only allowed in sandy bottom within 1 nautical mile of the Garden Key lighthouse. There is no anchoring allowed anywhere within the Research Natural Area (RNA)\"; RNA mooring buoys are day use only, maximum 2 hours. Private boaters buy a digital entrance pass in advance on Recreation.gov; \"Cash is not accepted.\" After Hurricane Ian, \"space for personal vessels is extremely limited\" at Garden Key."},{"name":"Laid Back Key West","source":"https://www.laidbackkeywest.com/","accessed":"2026-10-03","si":["ocean","diveglobal","yacht","group"],"booking_route":"own website enquiry; (303) 900-7200 per the NPS permitted-guide list","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":15,"blurb":"Listed by the NPS as a permitted guide for diving/snorkeling and guided fishing. Its own page offers a \"Private Dry Tortugas Charter from Key West\" and a \"Small-Group Dry Tortugas Day Trip from Key West\" (\"Fort Jefferson · Snorkeling · Fishing · 70 Miles Offshore\"). Hurricane Hole Marina, 5130 Overseas Hwy, Key West."},{"name":"Restless Native Charters","source":"https://www.restlessnative.com/","accessed":"2026-10-03","si":["sailing","romance","yacht"],"booking_route":"FareHarbor (own website)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":16,"blurb":"The only sailboat-tour operator on the NPS''s permitted-guide list for Dry Tortugas ((858) 775-1709). Its own site carries private captained charters with Captains Brad and Maddie, booked through FareHarbor."},{"name":"Key West Boat Charters","source":"https://www.kwboatcharters.com/","accessed":"2026-10-03","si":["yacht","ultra","romance","ocean"],"booking_route":"own website enquiry or (305) 304-0988","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":17,"blurb":"On the NPS motorized-tours permit list ((305) 304-0988). \"Key West Boat Charters is more than a brokerage service\"; a Dry Tortugas yacht trip to \"Explore a 19th Century Fort, known as Fort Jefferson, the largest brick building in the western hemisphere\", and \"The 90-foot luxury yacht, Mia\"."},{"name":"Dream Catcher Charters (Capt. Steven Lamp)","source":"https://www.fishingkeywest.com/","accessed":"2026-10-03","si":["ocean","adventure","group"],"booking_route":"own website or (305) 292-7212","commission_status":"unknown","commission":"guide","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":18,"blurb":"Listed by the NPS under eco tours, guided fishing and motorized tours ((305) 292-7212). \"Key West fishing guide since 1994\"; flats, reef, backcountry, deep-sea and Dry Tortugas fishing; \"4, 6 and 8 hour trips daily year round\"."},{"name":"Boyd''s Key West Campground","source":"https://www.boydscampground.com/","accessed":"2026-10-03","si":["motoring","family","caravan"],"booking_route":"own website (booking engine not identified on the page read)","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":19,"blurb":"\"Southernmost Hospitality Since 1963\", on waterfront Stock Island \"just 4 miles from Duval Street\": full hook-up RV sites (30/50 amp, water, sewer, cable), \"Scenic tent sites with picnic tables, grills\", tiny homes for two, RV rentals, heated pool, kayak and paddleboard rentals, pets welcome. 6401 Maloney Avenue."},{"name":"Leo''s Key West Campground","source":"https://www.leoscampground.com/","accessed":"2026-10-03","si":["motoring","caravan"],"booking_route":"RMS Cloud booking engine and bookeddirectly.com (own website links)","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":20,"blurb":"\"Closest campground to Key West\": \"Back-in, full hookup gravel sites that accommodate self-contained RV''s up to 42 feet\", larger premium sites with optional waterfront views, a camper or 1-bedroom apartment for no-RV stays, laundry, Wi-Fi, tiki huts, dog park and launch for kayaks and small dinghies. 5264 Suncrest Rd."},{"name":"Sugarloaf Key / Key West KOA Resort","source":"https://koa.com/campgrounds/sugarloaf-key/","accessed":"2026-10-03","si":["motoring","family","caravan"],"booking_route":"koa.com reservations","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":21,"blurb":"\"Located at Mile Marker 20 on US-1 in the Florida Keys\": RV sites with KOA Patios, Deluxe Cabins \"with full baths and linens\", tent sites, a year-round pool and the on-site Sugarloaf Key Hotel; \"Both our campground and the hotel are approximately a 30 minute drive from the main Key West area.\""},{"name":"Sugarloaf Key RV Resort & Cottages","source":"https://www.campspot.com/park/sugarloaf-key-rv-resort-and-cottages","accessed":"2026-10-03","si":["motoring","caravan","family"],"booking_route":"Campspot (instant booking)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"not-established","commission_pct_low":3,"commission_pct_high":3,"commission_basis":"published","wells":["stay"],"draw_rank":22,"blurb":"311 Johnson Road, Summerland Key: listed on Campspot as \"Waterfront, Fishing, Pool\", pets allowed, booked instantly on Campspot; the listing links it to Sun Outdoors Sugarloaf Key."},{"name":"Little Palm By The Sea","source":"https://www.hipcamp.com/en-US/land/florida-little-palm-by-the-sea-zwjh7yyd","accessed":"2026-10-03","si":["motoring","ocean"],"booking_route":"Hipcamp","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":23,"blurb":"A waterfront RV site on Kemp Channel in Venture Out, Cudjoe Key, \"25 miles to Key West\", with picnic table, boat slip and swim ladder; the gated community has a marina, heated pool and spa and an ocean swimming area. Hipcamp lists it \"Within a 60-minute drive from the Dry Tortugas Key West Eco Discovery Center.\""},{"name":"Casa Marina Key West, Curio Collection by Hilton","source":"https://www.casamarinaresort.com/","accessed":"2026-10-03","si":["romance","tropical","family","wellness"],"booking_route":"own website / hilton.com (brand booking)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":24,"blurb":"\"1920''s History in Key West with a New Contemporary Style\"; renovated, \"all 311 guestrooms, including 63 suites\"; the \"Largest Private Beach in Key West\", Spa al Mare and the beachfront restaurant Dorada."},{"name":"The Reach Key West, Curio Collection by Hilton","source":"https://www.reachresort.com/","accessed":"2026-10-03","si":["tropical","romance","family"],"booking_route":"own website / hilton.com (brand booking; the hilton.com page returned HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":25,"blurb":"Every room \"feature[s] their own balcony\"; the signature restaurant Four Marlins; \"Lounge by the oceanfront pool or feel the sand between your toes on the island''s only natural sand beach.\" Snorkeling, diving and fishing arranged from the resort."},{"name":"La Concha Key West, Autograph Collection","source":"https://www.laconchakeywest.com/","accessed":"2026-10-03","si":["culture","romance","senior"],"booking_route":"own website / marriott.com (brand booking; the marriott.com page returned HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":26,"blurb":"On Duval Street, a near-centennial landmark \"where Hemingway and Capone once roamed\"; after a comprehensive renovation it \"returns with renewed purpose– blending heritage, design, and modern luxury under Marriott''s Autograph Collection.\" Rooms from Double Queens to the Hemingway Suite and the Grand Dame Villas."},{"name":"Blue Heaven","source":"https://www.blueheavenkw.com/","accessed":"2026-10-03","si":["culinary","culture","family"],"booking_route":"walk-in; limited dinner reservations; 305-296-8666","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":27,"blurb":"729 Thomas Street, \"just two blocks from Duval\"; opened September 19, 1992 when \"Suanne the artist and Richard the writer cooked and served black beans, rice and fish to their first lunch customers on painted picnic tables under the Spanish Lime tree\"; \"featured in the MICHELIN Guide\". Breakfast and lunch first come, first served; limited dinner reservations."},{"name":"Louie''s Backyard","source":"https://www.louiesbackyard.com/","accessed":"2026-10-03","si":["culinary","romance"],"booking_route":"reservations (\"Reservations highly recommended\"); (305) 294-1061","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":28,"blurb":"700 Waddell Avenue: \"Island fare with a twist\", \"Where upscale dining meets the Atlantic Ocean\", with an upstairs café and the waterside Afterdeck Bar. The page read states \"We will be closed for vacation from September 8th until October 15th.\""},{"name":"Hogfish Bar & Grill","source":"https://www.hogfishbar.com/","accessed":"2026-10-03","si":["culinary","ocean"],"booking_route":"walk-in; 305-293-4041","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":29,"blurb":"6810 Front Street inside Safe Harbor Marina, Stock Island: \"a dockside seafood restaurant and bar\" with \"fresh local seafood straight off the boats, and a working-waterfront view. Come by boat or by car\"; Key West pink shrimp and fried hogfish; live music on the deck most weekends."},{"name":"El Siboney Restaurant","source":"https://www.elsiboneyrestaurant.com/","accessed":"2026-10-03","si":["culinary","family","culture"],"booking_route":"walk-in; call ahead for the paella","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":30,"blurb":"900 Catherine Street: \"Authentic Cuban Cuisine\" in a family-oriented restaurant; \"One of our signature offerings is the renowned Paella Valenciana\" - call at least one hour ahead to reserve it."},{"name":"Santiago''s Bodega","source":"https://www.santiagosbodega.com/","accessed":"2026-10-03","si":["culinary","wine","romance"],"booking_route":"phone 305-296-7691","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":31,"blurb":"207 Petronia Street: \"Fine Wines – Sangria – Tapas – Dessert\" in a dining room of \"mismatched chairs, custom art and reclaimed wood\"; 305-296-7691."},{"name":"Kermit''s Key Lime Shop","source":"https://www.kermitskeylime.com/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in; online shop","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat","shop"],"draw_rank":32,"blurb":"The Key West key lime shop: pies, pie bars and \"everything key lime flavored\", including gluten-free key lime pie, with online ordering for shipped desserts."},{"name":"Florida Keys Eco-Discovery Center","source":"https://floridakeys.noaa.gov/eco_discovery.html","accessed":"2026-10-03","si":["family","ocean","wildlife"],"booking_route":"none needed - walk in; groups email the centre a week ahead","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":33,"blurb":"Run by Florida Keys National Marine Sanctuary (NOAA) and listed by the NPS among Dry Tortugas visitor facilities: 6,000 square feet of exhibits on \"the only coral barrier reef in the continental United States\", a replica of the Aquarius undersea lab and a maritime-history exhibit; open Wednesday-Saturday, 9AM - 4PM."},{"name":"The Hemingway Home & Museum","source":"https://www.hemingwayhome.com/","accessed":"2026-10-03","si":["culture","senior","family"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":34,"blurb":"907 Whitehead Street: the museum is open every day, 9:00am-5:00pm for walk-in visits; \"Ernest Hemingway was given a white six-toed cat by a ship''s captain and some of the cats who live on the museum grounds are descendants of that original cat, named Snow White.\""},{"name":"Key West Lighthouse & Keeper''s Quarters","source":"https://www.kwahs.org/museums/lighthouse-keepers-quarters/","accessed":"2026-10-03","si":["culture","family","senior"],"booking_route":"own website tickets (Key West Art & Historical Society)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":35,"blurb":"938 Whitehead Street, across from the Hemingway Home: \"The current lighthouse opened in 1848 with a woman as its keeper\"; later fitted with a Third Order Fresnel Lens. Open Monday to Sunday 10:00 a.m. - 5:00 p.m. (last admission 4:30 p.m.); fully ADA accessible except the tower."},{"name":"Garden Key camping kit: tent, pad and strong stakes","source":"https://www.nps.gov/drto/planyourvisit/camping.htm","accessed":"2026-10-03","si":["adventure","tropical","ocean"],"booking_route":"affiliate referral to rei.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":36,"blurb":"NPS: \"Campers must bring all supplies, including a tent, fresh water, fuel, ice, and food.\" Bring a \"Tent (required), sleeping bag and pad, and strong stakes for the frequent high winds.\" \"There are no rentals or supplies for sale once you arrive.\""},{"name":"Snorkel gear that fits","source":"https://www.nps.gov/drto/planyourvisit/safety.htm","accessed":"2026-10-03","si":["diveglobal","ocean","tropical"],"booking_route":"affiliate referral to rei.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":37,"blurb":"NPS camping list: \"snorkel gear, binoculars, sunglasses and sunscreen\". \"Before snorkeling, make sure that all equipment fits properly.\" \"An approved dive flag must be displayed at all times when snorkeling outside of the designated snorkel area.\" Day-trippers on the ferry get loaner snorkel gear with the ticket."},{"name":"Reef-friendly mineral sunscreen","source":"https://www.nps.gov/drto/planyourvisit/safety.htm","accessed":"2026-10-03","si":["ocean","diveglobal","tropical"],"booking_route":"affiliate referral to amazon.com (Associates)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":3,"commission_basis":"published","wells":["gear"],"draw_rank":38,"blurb":"NPS: \"Make sure you bring anything that you may need, such as protective clothing, sunscreen, or medication ... You will not be able to purchase these items in the park.\" The park lies on \"the Florida Keys reef system, the third largest in the world\". NOAA (https://oceanservice.noaa.gov/news/sunscreen-corals.html, read 2026-10-03): \"specific (chemical) UV filters found in chemical sunscreen can harm aquatic life, including corals\"; \"Mineral sunscreen, which does not use (chemical) UV filters, is considered a better option.\""},{"name":"Sun shirt, long pants and wide-brimmed hat","source":"https://www.nps.gov/drto/planyourvisit/camping.htm","accessed":"2026-10-03","si":["tropical","ocean","adventure"],"booking_route":"affiliate referral to amazon.com (Associates)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":4,"commission_pct_high":4,"commission_basis":"published","wells":["gear"],"draw_rank":39,"blurb":"NPS: \"Be sure to arrive prepared with sun protection including breathable clothing, sunscreen, and a hat.\" Campers bring a \"lightweight long-sleeve shirt and pants for sun and bug protection, wide-brimmed hat.\" NOAA adds: \"use Ultraviolet Protection Factor (UPF) sunwear\"."},{"name":"Kayaker''s required kit: PFD, signal device, VHF radio","source":"https://www.nps.gov/drto/planyourvisit/paddlesports.htm","accessed":"2026-10-03","si":["adventure","ocean","sailing"],"booking_route":"affiliate referral to rei.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":40,"blurb":"NPS: \"Required equipment for any kayak use includes a PFD (Personal Floatation Device), a signaling device (typically a whistle and/or hand-held mirror) and a portable VHF radio. These items should be brought from the mainland by the kayaker, there are no services at the park.\""}],"faq":[{"q":"How far is Dry Tortugas National Park from Key West?","a":"\"Dry Tortugas National Park is a remote island park located about 70 miles (113 km) west of Key West, Florida. There are no roads to the park. Visitors can only reach Dry Tortugas by boat or seaplane.\"","source":"https://www.nps.gov/drto/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"Can you drive to Dry Tortugas National Park?","a":"No. \"Cars cannot access Dry Tortugas National Park. There are no bridges or roads connecting the park to the Florida Keys.\" \"Visitors must travel by ferry, seaplane, private boat, or permitted charter.\"","source":"https://www.nps.gov/drto/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"Can you fly to Dry Tortugas National Park?","a":"Yes, by seaplane from Key West. Key West Seaplane Adventures states: \"We are the only Seaplane Service permitted in Dry Tortugas National Park.\" \"Travel time is approximately 40 minutes each way\"; the half-day trip gives \"at least 2 1/2 hours of island time\" and the full day \"at least 6 1/2 hours\".","source":"https://keywestseaplanecharters.com/rates/","accessed":"2026-10-03"},{"q":"How much is Dry Tortugas National Park?","a":"\"The entrance fee for Dry Tortugas National Park is $15.00 per person and is good for 7 consecutive days. Any person 15 years old and under is exempt from paying an entrance fee.\" \"Ferry tickets include the cost of entrance to the park, but NOT camping fees.\" The park does not accept cash.","source":"https://www.nps.gov/drto/planyourvisit/fees.htm","accessed":"2026-10-03"},{"q":"Can you camp at Dry Tortugas National Park?","a":"Yes, on Garden Key only. \"Reservations are not accepted for the 6-person sites. All campers, once they arrive, will be guaranteed a place to camp.\" Sites are $15 a night; groups of 10-20 must reserve. \"Campers must bring all supplies, including a tent, fresh water, fuel, ice, and food\", and the ferry \"is limited to 10 camping passengers per day.\"","source":"https://www.nps.gov/drto/planyourvisit/camping.htm","accessed":"2026-10-03"},{"q":"Where should you stay when visiting Dry Tortugas National Park?","a":"Inside the park the only options are the Garden Key primitive campsites and, for private boaters, \"overnight on their vessels while anchored in designated areas.\" \"There are no restaurants, hotels, fuel stations, marine supplies, fishing supplies, or other gear available for rent or purchase on the island.\" Hotels and RV parks are in Key West, where the ferry and seaplane depart.","source":"https://www.nps.gov/drto/planyourvisit/eatingsleeping.htm","accessed":"2026-10-03"},{"q":"Can you snorkel in Dry Tortugas National Park?","a":"Yes. \"The swim areas on Garden Key are accessible via North, South, and East Beach. These beaches offer gradual slope and easy entry and are ideal for beginner swimmers and snorkelers.\" Off Loggerhead Key''s swim beach lies \"a remarkable coral formation aptly named Little Africa.\" \"No lifeguard on duty.\"","source":"https://www.nps.gov/drto/planyourvisit/swimming-beaches.htm","accessed":"2026-10-03"},{"q":"What is the best time to visit Dry Tortugas National Park?","a":"\"Park visitation is typically highest during February through April, the months that generally offer the most pleasant and comfortable weather conditions.\" Winter seas \"are generally rougher\" because it is windier; the summer wet season runs \"from about mid-May to November\", and hurricane season runs June 1 to November 30. For birds, \"Spring migration is the preferred season.\"","source":"https://www.nps.gov/drto/learn/nature/weather.htm","accessed":"2026-10-03"},{"q":"Is Dry Tortugas National Park dog friendly?","a":"Only partly: \"Pets are permitted on Garden Key but not inside Fort Jefferson. Pets are not permitted on any other key in the park.\" They must be leashed, and \"The commercial ferry and the seaplane do not allow pets onboard\" - pets come only by private boat or with a permitted tour guide.","source":"https://www.nps.gov/drto/planyourvisit/pets.htm","accessed":"2026-10-03"},{"q":"When was Dry Tortugas National Park established?","a":"Fort Jefferson National Monument was designated on January 4, 1935; \"The monument was expanded in 1983 and re-designated as Dry Tortugas National Park on October 26, 1992 by an act of Congress.\"","source":"https://www.nps.gov/drto/learn/historyculture/index.htm","accessed":"2026-10-03"}],"seo":{"meta_title":"Dry Tortugas National Park: Fort Jefferson, Ferry & Camping | TravelWell","meta_description":"Fort Jefferson 70 miles west of Key West, reached only by ferry or seaplane: $15 entry, Garden Key camping, snorkel beaches, and where to stay in Key West.","slug":"dry-tortugas-national-park-florida","primary_keyword":"Dry Tortugas National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Fort Jefferson Dry Tortugas aerial"}}'::jsonb, 44),
  ('blue-spring-florida', '12A', 'Blue Spring State Park', 'United States', 'Winter manatee refuge and spring run', 'future', 'verified', 'mountainValley', 'Florida - Gulf & Central', '{"wildlife","family","adventure","diveglobal","hiking","parks"}', '{"serene","family-friendly","historic"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Manatee viewing from the Spring Run boardwalk","source":"https://web.archive.org/web/20260701190554/https://www.floridastateparks.org/parks-and-trails/blue-spring-state-park/manatees-blue-spring-state-park","accessed":"2026-10-03","si":["wildlife","family","senior"],"booking_route":"park entry only - day-use reservation at reserve.floridastateparks.org ($6 per vehicle)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"\"From mid-November to March, hundreds of manatees congregate in the spring run to seek shelter from the cold\"; seen \"from the boardwalk, which stretches 1/3 of a mile from the St. Johns River to the headspring\" - \"socializing and mothers nursing their small calves\". Numbers grew \"from about 36 animals when research began in the 1970s to over 700 animals in 2023.\""},{"name":"Swimming in the Blue Spring Run","source":"https://web.archive.org/web/20260805235210/https://www.floridastateparks.org/parks-and-trails/blue-spring-state-park/experiences-amenities","accessed":"2026-10-03","si":["family","adventure"],"booking_route":"park entry only - day-use reservation","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"\"Blue Spring offers swimming in a crystal-clear spring run\" in 72-degree water, open \"annually from April 1 to November 14\"; \"Swimming or diving with the manatees is not permitted\"; food, coolers, glass, pets and inflatables over 72 inches are among the items prohibited on the water."},{"name":"St. Johns River Nature Cruise","source":"https://bluespringadventures.com/st-johns-river-nature-cruise/","accessed":"2026-10-03","si":["wildlife","family","senior","river"],"booking_route":"FareHarbor (own website, bluespringadventures.com) or 833-953-2583","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":3,"blurb":"A 2-hour narrated cruise \"setting sail from the docks at Blue Spring State Park\"; wildlife \"including majestic wading birds, gentle manatees, vibrant aquatic plant life, enchanting cypress forests, and the occasional glimpse of awe-inspiring alligators\". Florida State Parks lists departures \"daily at 10 a.m. and 1 p.m.\" and a Platinum Level certification from the Florida Society for Ethical Ecotourism."},{"name":"Thursby House","source":"https://web.archive.org/web/20260217231123/https://www.floridastateparks.org/parks-and-trails/blue-spring-state-park/history","accessed":"2026-10-03","si":["culture","senior","family"],"booking_route":"none needed - included in park admission","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"\"The Thursby House was built by Louis Thursby in 1872 and became a hub of activity on the St. Johns River, hosting steamboat passengers\"; Thursby, a \"Gold Rush prospector turned orange-grower\", bought Blue Spring in 1856, and \"Mrs. Thursby was Orange City''s first postmistress.\" Interpretive exhibits inside; the first floor is accessible."},{"name":"Blue Spring State Park Campground","source":"https://web.archive.org/web/20260805235210/https://www.floridastateparks.org/parks-and-trails/blue-spring-state-park/experiences-amenities","accessed":"2026-10-03","si":["family","motoring","senior"],"booking_route":"Florida State Parks reservations website or 800-326-3521","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":5,"blurb":"\"51 campsites (recreational vehicles up to 40 feet long) located in the sand pine scrub and within walking distance of the spring. Each site is equipped with a picnic table, water, electricity and a grill.\" Dump station; accessible sites; pets welcome under the park pet policy. $24 a night plus tax, a $6.70 reservation fee and a $7 nightly RV utility fee."},{"name":"Blue Spring cabins","source":"https://web.archive.org/web/20260805235210/https://www.floridastateparks.org/parks-and-trails/blue-spring-state-park/experiences-amenities","accessed":"2026-10-03","si":["family","senior","romance"],"booking_route":"Florida State Parks reservations website or 800-326-3521, up to 11 months ahead","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":6,"blurb":"\"Six two-bedroom cabins are located in a shady oak hammock near Blue Spring\"; up to six people (three beds), electric fireplace (November-March), central heating and cooling, full kitchen, screened porch; \"televisions and phones are not provided\"; two-night minimum; pets not permitted; Cabin 2 accessible. $95 a night plus tax and fees."},{"name":"Scuba diving in Blue Spring","source":"https://web.archive.org/web/20260805235210/https://www.floridastateparks.org/parks-and-trails/blue-spring-state-park/experiences-amenities","accessed":"2026-10-03","si":["diveglobal","adventure"],"booking_route":"none needed for certified divers - park entry only","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"\"Scuba diving is a popular activity in the spring\"; \"Capacity is limited to 32 scuba diving individuals at one time\"; open water divers are \"prohibited from carrying lights and diving below 60 feet\"; dives \"completed one hour before sunset\"; keep \"a minimum distance of 50 feet between you and manatees at all times.\""},{"name":"Tubing the spring run","source":"https://bluespringadventures.com/faqs/","accessed":"2026-10-03","si":["family","adventure"],"booking_route":"walk-in at the park rental station","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":8,"blurb":"\"You can enter the water at the upper entry, swim to the spring boil and float back down to the main swim dock. The float run lasts about an eighth of a mile.\" Rentals from Blue Spring Adventures: \"Single tubes start at $7 for the first hour\"; \"Tubing is walk-in only\" and summer only."},{"name":"Pine Island Trail","source":"https://web.archive.org/web/20260805235210/https://www.floridastateparks.org/parks-and-trails/blue-spring-state-park/experiences-amenities","accessed":"2026-10-03","si":["hiking","wildlife"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"\"Pine Island Trail is 3.6 miles in length (one way) and takes you through numerous plant communities from the desert-like scrub to the blackwater stream known as the St. Johns River.\" The park''s photo gallery carries a \"Black Bear on the Pine Island Trail\"."},{"name":"Sand Pine Scrub Trail and the Florida scrub-jay","source":"https://web.archive.org/web/20260805235210/https://www.floridastateparks.org/parks-and-trails/blue-spring-state-park/experiences-amenities","accessed":"2026-10-03","si":["wildlife","hiking","senior"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"\"Sand Pine Scrub Trail is a 0.25 loop located between the Blue Spring main office and the campground. Look for the endemic Florida scrub-jay on this trail.\" \"Feeding Florida scrub-jays is against the law.\""},{"name":"Paddling Blue Spring Run and the St. Johns River","source":"https://web.archive.org/web/20260805235210/https://www.floridastateparks.org/parks-and-trails/blue-spring-state-park/experiences-amenities","accessed":"2026-10-03","si":["adventure","river","wildlife"],"booking_route":"none needed with your own boat; \"there is no launching fee\" (Blue Spring Adventures FAQ)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":11,"blurb":"\"You are invited to canoe beautiful Blue Spring Run and the St. Johns River\"; personal boats launch \"at the canoe kayak rental beach located in the lower day use area\"; \"Paddling is not allowed in the swimming area between 10 a.m. and 5 p.m.\"; the run closes to boating in manatee season."},{"name":"St. Johns River fishing dock","source":"https://web.archive.org/web/20260805235210/https://www.floridastateparks.org/parks-and-trails/blue-spring-state-park/experiences-amenities","accessed":"2026-10-03","si":["adventure","senior"],"booking_route":"none needed - park entry; FWC licence where required","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":12,"blurb":"\"Visitors can fish from the accessible fishing dock on the St. Johns River. Fishing is not permitted in the Blue Spring Run\"; \"A fishing license may be required\" under Florida Fish and Wildlife Conservation Commission rules."},{"name":"Manatee Gift Shop, canteen and camp store","source":"https://bluespringadventures.com/","accessed":"2026-10-03","si":["family"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat","shop"],"draw_rank":13,"blurb":"\"The Manatee Gift Shop, food service, camp store and water activities rental station are located near the public swimming area\"; Blue Spring Adventures lists retail and canteen hours \"Daily 9am - 4pm\"."},{"name":"Picnic pavilions and playground","source":"https://web.archive.org/web/20260805235210/https://www.floridastateparks.org/parks-and-trails/blue-spring-state-park/experiences-amenities","accessed":"2026-10-03","si":["family"],"booking_route":"none needed - first come, first served","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":14,"blurb":"\"Three accessible picnic pavilions are offered that have stand-up grills. There is also a large accessible barbecue grill by the pavilions near the river\"; \"All pavilions are first come, first served\"; \"A playground is located in the lower day-use area.\""},{"name":"Blue Spring Adventures rentals and kayak tour","source":"https://bluespringadventures.com/","accessed":"2026-10-03","si":["adventure","family","river"],"booking_route":"FareHarbor (own website)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":15,"blurb":"The park concessionaire: \"We offer kayaks and canoes for self-guided hourly rentals\", e-bike rentals, a guided kayak tour, and a \"narrated 2 hour boat charter for up to 50 guests\". \"Kayaks and canoes must be reserved in advance. No same day bookings available. Kayaking in the spring is prohibited.\" 833-953-2583."},{"name":"Florida Dive Company - Blue Spring tours","source":"https://floridadivecompany.com/pages/blue-spring-state-park-dive-snorkel-tours","accessed":"2026-10-03","si":["diveglobal","group","adventure","family"],"booking_route":"FareHarbor, online only (\"we do not accept over the phone payments or bookings\")","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":16,"blurb":"Group Snorkel Tour \"$65 per person\" (45-60 minutes, ages 10+), Try Scuba \"From $150 per person\", Group Scuba Tour \"$85 per person\" (Open Water certification); season \"April 1 to November 14\"; Wednesday-Sunday, 6:30 AM-1 PM; meets in the upper day-use area. 386.663.8030."},{"name":"Hontoon Island Adventures","source":"https://hontoonislandadventures.com/","accessed":"2026-10-03","si":["adventure","family","river"],"booking_route":"own website","commission_status":"unknown","commission":"operator","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":17,"blurb":"\"Just a short, free ferry ride from the mainland\" at Hontoon Landing: kayak, canoe, bike, pontoon and jon boat rentals, \"rustic cabins or primitive campsites\", moorage slips \"with electric and water\", and the option to \"cruise to nearby Blue Spring by kayak.\" Concession for Hontoon Island State Park."},{"name":"Courtyard by Marriott DeLand Historic Downtown","source":"https://web.archive.org/web/20251207045602/https://www.marriott.com/en-us/hotels/dabdl-courtyard-deland-historic-downtown/overview/","accessed":"2026-10-03","si":["culture","family","senior"],"booking_route":"marriott.com (brand booking)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":18,"blurb":"\"Ideally located within walking distance of Stetson University and the shops and restaurants of Main Street DeLand\"; the hotel itself names \"nearby attractions like Blue Spring State Park\"; outdoor pool, gym, The Bistro; pets welcome ($50 one-time fee). +1 386-943-9500. Read from Marriott''s page as archived 2025-12-07 (the live page returned HTTP 403)."},{"name":"Hampton Inn Debary-Deltona","source":"https://www.booking.com/city/us/orange-city.html","accessed":"2026-10-03","si":["family","senior"],"booking_route":"hilton.com (brand booking; not fetched - HTTP 403) or Booking.com","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":19,"blurb":"Booking.com: \"located in DeBary, 10 miles from Blue Springs State Park\"; \"This 3-star hotel offers a 24-hour front desk and free WiFi.\" Hilton''s own page refused the fetch (HTTP 403)."},{"name":"Holiday Inn Express & Suites Deland South by IHG","source":"https://www.booking.com/city/us/orange-city.html","accessed":"2026-10-03","si":["family"],"booking_route":"ihg.com (brand booking; not fetched - HTTP 403) or Booking.com","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":20,"blurb":"Booking.com: \"located in De Land, within 5.7 miles of Blue Springs State Park and 2.8 miles of Spec Martin Stadium.\" IHG''s own page refused the fetch (HTTP 403)."},{"name":"Holiday Inn Express Hotel & Suites Orange City - Deltona by IHG","source":"https://www.booking.com/city/us/orange-city.html","accessed":"2026-10-03","si":["family"],"booking_route":"ihg.com (brand booking; not fetched - HTTP 403) or Booking.com","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":21,"blurb":"Booking.com: \"Located in central Orange City, this hotel is adjacent to Deltona Memorial Gardens. Features include a outdoor swimming pool, free full breakfast\". IHG''s own page refused the fetch (HTTP 403)."},{"name":"Hontoon Landing Resort & Marina","source":"https://www.booking.com/city/us/orange-city.html","accessed":"2026-10-03","si":["river","family","adventure"],"booking_route":"Booking.com (own site unreachable)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"not-established","commission_pct_low":4,"commission_basis":"published","wells":["stay"],"draw_rank":22,"blurb":"Booking.com: \"Located in De Land, 14 miles from Blue Springs State Park, Hontoon Landing Resort & Marina has accommodations with an outdoor swimming pool, free private parking and a terrace.\" The departure point for the free Hontoon Island ferry (Hontoon Island Adventures). Its own site did not resolve."},{"name":"Orange City RV Resort","source":"https://www.campspot.com/c/rv-camping-in-florida/near-blue-springs-state-park","accessed":"2026-10-03","si":["motoring","family","senior"],"booking_route":"Campspot (campspot.com/park/orange-city)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"not-established","commission_pct_low":3,"commission_pct_high":3,"commission_basis":"published","wells":["stay"],"draw_rank":23,"blurb":"Campspot: 4 miles straight-line from the park; \"The pull-thru RV sites are perfect for bigger rigs and include full hookup, cable, and Wi-Fi. Don''t have an RV? Rent one of the comfortable, onsite RV units\"; pool, hot tub, bocce, kiddie pool; \"A short, 45-minute drive to Orlando''s many attractions\". Starting at $42.00."},{"name":"Paradise Lakes - Deltona","source":"https://www.campspot.com/c/rv-camping-in-florida/near-blue-springs-state-park","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"Campspot (campspot.com/park/paradise-lakes-deltona-fl)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"not-established","commission_pct_low":3,"commission_pct_high":3,"commission_basis":"published","wells":["stay"],"draw_rank":24,"blurb":"Campspot: 8 miles straight-line; \"Ideally situated in Deltona, the campground provides easy access to the thrills of Universal Orlando Resort\" and Daytona; relaxation \"on-site by the peaceful lake\", cornhole and horseshoes; \"New to Campspot!\", starting at $60.00, no ratings yet."},{"name":"Luna Sands Resort","source":"https://lunasandsrvresort.com/","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"phone (386) 775-3996 or info@lunasandsrvresort.com","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":25,"blurb":"1440 E Minnesota Ave, Orange City: \"With over 120 sites, plus 6 additional overflow sites\"; back-in and pull-through 30/50 amp RV sites with sewer, 20 amp water-and-electric sites, campsites and cabins; pool, clubhouse, tiki bar, general store, \"themed weekend events from November through April\". (386) 775-3996."},{"name":"Daytona''s Endless Summer Campground","source":"https://www.campspot.com/c/rv-camping-in-florida/near-blue-springs-state-park","accessed":"2026-10-03","si":["family","motoring"],"booking_route":"Campspot (campspot.com/park/daytonas-endless-summer-campground-port-orange-fl)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"not-established","commission_pct_low":3,"commission_pct_high":3,"commission_basis":"published","wells":["stay"],"draw_rank":26,"blurb":"Campspot: 24 miles straight-line, 3520 S. Nova Road, Port Orange: \"full-hookup 30/50 AMP RV sites—including select big-rig pull-throughs up to 75 feet—alongside classic cabins, deluxe cabins with private bathrooms, and spacious two-bedroom lodges\"; a \"43,000-gallon year-round pool\". Starting at $54.00."},{"name":"St. John''s River Campground, Astor","source":"https://www.stjohnsrivercampground.com/","accessed":"2026-10-03","si":["motoring","river"],"booking_route":"phone 352-636-3139","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":27,"blurb":"\"Enjoy camping in one of our shady camp sites located just 1/4 mile from the beautiful St. Johns River\"; \"Full hook-ups for RV''s\", cabin rentals, recreation room, laundromat and showers; daily, weekly or monthly rates; \"Call 1-352-636-3139 today to reserve your camp site\"."},{"name":"Beautiful Bell Tent Nestled Amidst Trees, Seville","source":"https://glampinghub.com/unitedstatesofamerica/southeast/florida/seville/beautiful-bell-tent-nestled-amidst-trees-seville-florida/","accessed":"2026-10-03","si":["glamping","romance"],"booking_route":"Glamping Hub enquiry / availability check","commission_status":"none","commission":"affiliate","tier_absent_reason":"not-established","commission_basis":"published","wells":["stay"],"draw_rank":28,"blurb":"Glamping Hub bell tent for \"2 guests • 1 bedroom • 1 bed • 1 bathroom\" with a queen bed, heating, Wi-Fi, electricity, water and lake access; pets allowed; check-in \"From 03:00 PM\". \"This is a new property on Glamping Hub, there are no reviews yet.\" Surfaced on Glamping Hub''s DeLand search page."},{"name":"De Leon Springs State Park","source":"https://web.archive.org/web/20260802012733/https://www.floridastateparks.org/parks-and-trails/blue-spring-state-park","accessed":"2026-10-03","si":["family","adventure"],"booking_route":"Florida State Parks entry (fee not read in this build)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":29,"blurb":"Named by Florida State Parks among places near Blue Spring: \"a recreational swimming area and a fascinating history\" at 601 Ponce De Leon Blvd., De Leon Springs. Glamping Hub''s DeLand page adds \"you can take a dip 25 feet down to the mouth of the springs.\""},{"name":"Downtown DeLand Main Street","source":"https://mainstreetdeland.org/dine","accessed":"2026-10-03","si":["culture","culinary","senior"],"booking_route":"none needed - a public downtown","commission_status":"none","tier_absent_reason":"not-sold","wells":["shop","eat"],"draw_rank":30,"blurb":"MainStreet DeLand: \"Independent restaurants, cafes, bakeries, and coffee shops abound. Gourmet, scratch-made, locally sourced\" - Greek, Cuban, Mexican, Thai and Italian. Glamping Hub''s DeLand page: \"founded in 1876 and is home to Stetson University, Florida''s oldest college.\""},{"name":"Cress Restaurant","source":"https://www.cressrestaurant.com/","accessed":"2026-10-03","si":["culinary","romance","wine"],"booking_route":"online reservations from the own website; call for 12 or more","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":31,"blurb":"103 W. Indiana Ave, DeLand: \"We are a 2026 DiRoNA Award Recipient\"; lamb, duck and game meats; the wine list \"has be[en] recognized with Wine Spectator''s Award of Excellence 4 years running 2022, 2023, 2024, 2025\". (386) 734-3740 (MainStreet DeLand listing)."},{"name":"De La Vega Restaurante y Galleria","source":"https://delavegart.com/","accessed":"2026-10-03","si":["culinary","wine","romance"],"booking_route":"phone (386) 734-4444 (no booking method read on the page)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":32,"blurb":"128 N. Woodland Blvd., DeLand, (386) 734-4444 (MainStreet DeLand listing); its own site calls it \"Latin Fusion Wine Tapas Sangria – Downtown DeLand FL\"."},{"name":"Persimmon Hollow Brewing Co.","source":"https://www.persimmonhollowbrewing.com/","accessed":"2026-10-03","si":["culinary"],"booking_route":"walk-in taproom","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":33,"blurb":"Downtown DeLand taproom of a local brewery, with a Mug Club and \"Find Our Beer Near You\" listings; tagline \"drink sensibly, but get weird.\" Taproom hours and address were not printed in the page text read."},{"name":"Forno Bello Wood Fired Pizza & Italian Cuisine","source":"https://mainstreetdeland.org/dine","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"phone 386-279-0078","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":34,"blurb":"138 S. Woodland Blvd, DeLand, 386-279-0078 - listed by MainStreet DeLand among downtown restaurants. Its own site (fornobellodeland.com) returned no readable text."},{"name":"Trilogy Coffee Roasting Co.","source":"http://trilogycoffee.com","accessed":"2026-10-03","si":["culinary"],"booking_route":"walk-in; online shop for beans","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat","shop"],"draw_rank":35,"blurb":"\"We are Trilogy Coffee Roasting Co. located in historic Downtown DeLand, Florida\"; roasting since at least 2014 (\"serving our wholesale customers since 2014\"); 136 W. Georgia Avenue, (386) 624-6057 (MainStreet DeLand listing)."},{"name":"Boston Coffeehouse","source":"https://www.bostoncoffeehouse.com/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in or online order","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":36,"blurb":"\"Celebrating 30 years of being part of the communities we serve. With five locations and awards for Best Coffeehouse, Best Lunch, and Best Drinks\"; sandwiches and specialty coffee. DeLand location 109 East New York Avenue, 386-738-2326 (MainStreet DeLand listing)."},{"name":"Pat and Toni''s Sweet Things","source":"https://www.patandtonissweetthings.com/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in or online shop","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat","shop"],"draw_rank":37,"blurb":"\"Handmade Chocolates, Fudge, Candy, and Frozen Treats\" - a chocolate shop in DeLand that also ships handmade chocolates across the U.S.; 124 N. Woodland Blvd., 386-734-0066 (MainStreet DeLand listing)."},{"name":"Cafe DaVinci DeLand","source":"https://www.cafedavincideland.com/","accessed":"2026-10-03","si":["entertainment","culinary"],"booking_route":"walk-in (show listings on the own website)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":38,"blurb":"\"DeLand''s Best Original Live Music Venue\" - \"Drink Local, Dance Local\", with upcoming shows and specials listed on its own site."}],"faq":[{"q":"Can you swim at Blue Spring State Park?","a":"Yes, in season: \"Swimming in the spring run is open annually from April 1 to November 14. Reopening may be slightly delayed if a significant number of manatees remain in the spring.\" From November 15 to March 31, \"swimming and all other water activities in the spring run are prohibited to protect the manatees.\"","source":"https://web.archive.org/web/20260805235210/https://www.floridastateparks.org/parks-and-trails/blue-spring-state-park/experiences-amenities","accessed":"2026-10-03"},{"q":"When is manatee season at Blue Spring State Park?","a":"\"Manatee season runs from November 15 to March 31, when manatees rely on the spring''s constant 72 °F water for survival.\" Florida State Parks adds that the closure dates \"may begin sooner and end later depending on manatee presence.\"","source":"https://web.archive.org/web/20260805235210/https://www.floridastateparks.org/parks-and-trails/blue-spring-state-park/experiences-amenities","accessed":"2026-10-03"},{"q":"Can you swim with manatees at Blue Spring State Park?","a":"No. \"Swimming or diving with the manatees is not permitted.\" Divers must \"Keep a minimum distance of 50 feet between you and manatees at all times.\" Manatees are viewed from the boardwalk, which \"stretches 1/3 of a mile from the St. Johns River to the headspring.\"","source":"https://web.archive.org/web/20260805235210/https://www.floridastateparks.org/parks-and-trails/blue-spring-state-park/experiences-amenities","accessed":"2026-10-03"},{"q":"What is the entrance fee at Blue Spring State Park?","a":"\"$6 per vehicle (two to eight people). $4 single-occupant vehicle. $2 pedestrians, bicyclists, extra passengers, passengers in vehicle with holder of Annual Individual Entrance Pass.\"","source":"https://web.archive.org/web/20260802030124/https://www.floridastateparks.org/parks-and-trails/blue-spring-state-park/hours-fees","accessed":"2026-10-03"},{"q":"Do you need reservations for Blue Spring State Park?","a":"Yes: \"Beginning July 15, 2026, all visitors to Blue Spring State Park, including Florida State Parks annual passholders, pedestrians and cyclists, must have a reservation to enter the park.\" \"Reservations can be made up to 60 days in advance. Same-day reservations may be made until the reservation limit has been met.\" A camping or concession booking also admits you.","source":"https://web.archive.org/web/20260709002259/https://www.floridastateparks.org/learn/frequently-asked-questions-blue-spring-day-use","accessed":"2026-10-03"},{"q":"Can you camp at Blue Spring State Park?","a":"Yes. \"The campground has 51 campsites (recreational vehicles up to 40 feet long) located in the sand pine scrub and within walking distance of the spring. Each site is equipped with a picnic table, water, electricity and a grill.\" There are also six two-bedroom cabins. Reserve through the Florida State Parks reservations website or 800-326-3521.","source":"https://web.archive.org/web/20260805235210/https://www.floridastateparks.org/parks-and-trails/blue-spring-state-park/experiences-amenities","accessed":"2026-10-03"},{"q":"Is Blue Spring State Park dog friendly?","a":"Partly. The park concessionaire''s FAQ: \"Pets are permitted in the park only in designated areas, but must be leashed. Pets are not allowed in the water. Pets are not permitted onboard tour boats.\" Florida State Parks welcomes pets in the camping area under its pet policy, but \"Pets are not permitted in cabins.\"","source":"https://bluespringadventures.com/faqs/","accessed":"2026-10-03"},{"q":"Does Blue Spring State Park have alligators?","a":"On the St. Johns River, yes: the park''s nature cruise operator lists \"majestic wading birds, gentle manatees, vibrant aquatic plant life, enchanting cypress forests, and the occasional glimpse of awe-inspiring alligators\", and notes that \"sightings vary from day to day.\"","source":"https://bluespringadventures.com/st-johns-river-nature-cruise/","accessed":"2026-10-03"},{"q":"How far is Blue Spring State Park from Orlando?","a":"The park''s cruise operator says it is \"Located just 45 minutes away from both Orlando and Daytona.\"","source":"https://bluespringadventures.com/st-johns-river-nature-cruise/","accessed":"2026-10-03"},{"q":"When does Blue Spring State Park open?","a":"\"The park is open from 8 a.m. until sundown, 365 days a year.\" Campers arriving after sunset should call 386-775-3663 on the day of arrival for the gate combination.","source":"https://web.archive.org/web/20260802030124/https://www.floridastateparks.org/parks-and-trails/blue-spring-state-park/hours-fees","accessed":"2026-10-03"}],"seo":{"meta_title":"Blue Spring State Park: Manatees, Spring Run & Camping | TravelWell","meta_description":"Winter manatee refuge on the St. Johns River: a 1/3-mile boardwalk, spring-run swimming April to mid-November, cabins, campground and river cruises.","slug":"blue-spring-state-park-florida","primary_keyword":"Blue Spring State Park","jsonld_type":"TouristDestination"},"hero":{"query":"Blue Spring State Park manatees boardwalk"}}'::jsonb, 45),
  ('honeymoon-island-florida', '12A', 'Honeymoon Island State Park', 'United States', 'Gulf barrier-island beaches and virgin slash pines', 'future', 'verified', 'mountainValley', 'Florida - Gulf & Central', '{"wildlife","family","romance","adventure","hiking","parks"}', '{"coastal","serene","family-friendly","romantic"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Honeymoon Island beaches","source":"https://web.archive.org/web/20260902182917/https://www.floridastateparks.org/parks-and-trails/honeymoon-island-state-park/experiences-amenities","accessed":"2026-10-03","si":["family","tropical","romance","senior"],"booking_route":"none needed - included in park admission ($8 per vehicle)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"\"With approximately four miles of shoreline\": \"areas designated for swimming on the main beach, a pet beach on the south end, and great shelling and walking on the north end, which turns into a sand spit\"; rinse showers by the boardwalks; warning flags posted, and \"Lifeguards are not provided.\""},{"name":"Caladesi Island Ferry","source":"https://caladesiferry.org/schedules-and-pricing/","accessed":"2026-10-03","si":["family","ocean","wildlife","romance"],"booking_route":"walk-up ticket office at Honeymoon Island State Park only - \"Tickets are not available for purchase online\"","commission_status":"none","commission":"operator","tier_absent_reason":"does-not-compete","wells":["move","activities"],"draw_rank":2,"blurb":"Two ferry boats from the Honeymoon Island docks to Caladesi Island, \"3 Miles of pristine beaches accessible only by boat\"; hourly from 10am all year, half-hourly mid-February to Labor Day and weekends; round trip \"Adults $20\", \"Children (6-12) $10\", \"5 and Under Free\"; \"Tickets are not available for purchase online!\" - bought at the ticket office in Honeymoon Island State Park. 727-734-5263."},{"name":"Osprey Trail","source":"https://web.archive.org/web/20260810070135/https://www.floridastateparks.org/parks-and-trails/honeymoon-island-state-park/history","accessed":"2026-10-03","si":["hiking","wildlife","senior"],"booking_route":"none needed - included in park admission","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"\"Observe one of the few remaining South Florida virgin slash pine stands along the Osprey Trail, which provides visitors with 2.5 miles of walking\"; some of the trees \"are almost 200 years old\", with bald eagles, osprey and great horned owls nesting in winter and spring and a large gopher tortoise population. Leashed dogs allowed."},{"name":"Rotary Centennial Nature Center","source":"https://web.archive.org/web/20260902182917/https://www.floridastateparks.org/parks-and-trails/honeymoon-island-state-park/experiences-amenities","accessed":"2026-10-03","si":["wildlife","family","senior","culture"],"booking_route":"none needed - included in park admission","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"\"a great place to learn about the history of Honeymoon and Caladesi Islands as well as find information on the plants and animals that can be found on the islands\"; \"open 9 a.m. to 5 p.m. Wednesday through Sunday\"; its elevated observation deck \"at low tide provides many opportunities to see wading birds around the seagrass beds in the St. Joseph Sound.\""},{"name":"Pet Beach","source":"https://web.archive.org/web/20260902182917/https://www.floridastateparks.org/parks-and-trails/honeymoon-island-state-park/experiences-amenities","accessed":"2026-10-03","si":["family","senior"],"booking_route":"none needed - included in park admission","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"\"Dogs are allowed in designated areas such as the pet beach on the southern tip of the island and on the nature trail. Pets must be on a 6-foot hand-held leash at all times in these areas.\" Owners must pick up after their pets."},{"name":"North-end sand spit and shelling","source":"https://web.archive.org/web/20260909134454/https://www.floridastateparks.org/parks-and-trails/honeymoon-island-state-park","accessed":"2026-10-03","si":["wildlife","family"],"booking_route":"none needed - included in park admission","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":6,"blurb":"\"great shelling and walking on the north end, which turns into a sand spit.\" Since April 9, 2024, \"Erosion and sand migration have separated the northernmost mile\" of the sandspit, \"forming a temporary cut\"; the park says \"do not venture into or through the water.\""},{"name":"Pelican Cove paddling","source":"https://web.archive.org/web/20260902182917/https://www.floridastateparks.org/parks-and-trails/honeymoon-island-state-park/experiences-amenities","accessed":"2026-10-03","si":["adventure","wildlife","ocean"],"booking_route":"bring your own kayak, or rent at the park concession (Florida Beach Services)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":7,"blurb":"\"Kayaks can be rented through the concession or, if you have your own, explore Pelican Cove, which lies between the sand spit and nature trail.\""},{"name":"Cafe Honeymoon and the park concession","source":"https://web.archive.org/web/20260902182917/https://www.floridastateparks.org/parks-and-trails/honeymoon-island-state-park/experiences-amenities","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in; Cafe Honeymoon 727-736-2132","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat","shop","gear"],"draw_rank":8,"blurb":"\"Florida Beach Services offers casual beach fare, has a small gift shop and is located steps away from the ferry dock\"; the concession \"offers food, beverages, beach supplies and souvenirs. Kayaks, umbrellas and beach chairs are available for rent.\" Alcohol is prohibited in the park \"except at the restaurant in the park where alcohol is sold.\" Cafe Honeymoon 727-736-2132."},{"name":"Beach weddings at the Honeymoon Pavilion","source":"https://romantichoneymoonisland.com/","accessed":"2026-10-03","si":["romance","group"],"booking_route":"enquiry by phone (727) 260-5503 or the site''s contact page; deposits handled by the venue","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities","eat"],"draw_rank":9,"blurb":"The in-park events team: \"Having hosted hundreds of weddings on the beaches of Tampa Bay, our experienced event team can customize your Wedding Package for Honeymoon Island\"; \"Wedding Ceremonies and Private Beachfront Receptions\", plus corporate meetings and private parties at the Pavilion. (727) 260-5503."},{"name":"Picnic area and Limitless playground","source":"https://web.archive.org/web/20260902182917/https://www.floridastateparks.org/parks-and-trails/honeymoon-island-state-park/experiences-amenities","accessed":"2026-10-03","si":["family","senior"],"booking_route":"none needed - first-come, first-served, included in park admission","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"\"A picnic area is located on the northern end of the island. There are picnic tables, two covered pavilions, restrooms and barbecue grills\"; the pavilions are \"non-reservable\" and first-come, first-served; \"There is a Limitless playground located in the picnic area on the north end of the island.\""},{"name":"Surf and pass fishing","source":"https://web.archive.org/web/20260902182917/https://www.floridastateparks.org/parks-and-trails/honeymoon-island-state-park/experiences-amenities","accessed":"2026-10-03","si":["adventure","ocean"],"booking_route":"none needed in the park - Florida fishing licence rules apply (FWC)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":11,"blurb":"\"Surf and pass fishing can yield catches of flounder, snook, trout, redfish, snapper, whiting, sheepshead, pompano, Spanish mackerel, cobia, ladyfish and tarpon\"; all fishing must follow state rules and \"A fishing license may be required.\""},{"name":"Surfing by bathhouse 3","source":"https://web.archive.org/web/20260902182917/https://www.floridastateparks.org/parks-and-trails/honeymoon-island-state-park/experiences-amenities","accessed":"2026-10-03","si":["adventure","ocean"],"booking_route":"none needed - included in park admission","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":12,"blurb":"\"Surfing is allowed in the park, and it''s usually pretty good on the north end by bathhouse 3.\""},{"name":"Wheel Fun Rentals bicycles and surreys","source":"https://web.archive.org/web/20260902182917/https://www.floridastateparks.org/parks-and-trails/honeymoon-island-state-park/experiences-amenities","accessed":"2026-10-03","si":["family","adventure"],"booking_route":"rent on site (operator page not reached - HTTP 404)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["gear","move"],"draw_rank":13,"blurb":"Florida State Parks: \"Spend the day exploring beautiful Honeymoon Island with Wheel Fun Rentals... multi-passenger Surreys and beach cruisers. Ride to your heart''s content on paved trails throughout the island.\" Florida law requires helmets for cyclists 16 and under. The operator''s own location page returned 404 when fetched."},{"name":"Caladesi Island State Park","source":"https://web.archive.org/web/20260922125903/https://www.floridastateparks.org/parks-and-trails/caladesi-island-state-park/experiences-amenities","accessed":"2026-10-03","si":["wildlife","adventure","family","romance"],"booking_route":"reached by the Caladesi Island Ferry from Honeymoon Island, by kayak, or by private boat","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":14,"blurb":"\"One of the few untouched islands along the Gulf Coast, Caladesi Island State Park is accessible only by boat\"; nature trails to the historic Scharrer Homestead; \"over 3 miles of paddling through the majestic mangrove tunnels\"; shelling for \"conchs, whelks and olives\" (live shelling prohibited); the park calls itself \"America''s Best Beach in 2008\"."},{"name":"Caladesi Island marina boat camping","source":"https://web.archive.org/web/20260922125903/https://www.floridastateparks.org/parks-and-trails/caladesi-island-state-park/experiences-amenities","accessed":"2026-10-03","si":["sailing","yacht","adventure"],"booking_route":"Florida State Parks reservations website or 800-326-3521; first-come, first-served at the marina","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":15,"blurb":"\"Caladesi Island State Park has a marina with floating docks with 50 amp electric service and water hookups\"; overnight docking in the \"108-slip bayside marina\" with registration before sundown; \"Fees are $24 per night, plus tax, plus a nonrefundable $6.70 reservation fee or $1 per foot, plus tax\"; three sites ADA accessible."},{"name":"Sail Honeymoon Kayak & SUP Rentals","source":"https://www.sailhoneymoon.com/","accessed":"2026-10-03","si":["adventure","wildlife","family"],"booking_route":"walk-up, no reservations; phone (727) 734-0392","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":16,"blurb":"On the Dunedin Causeway: kayak and stand-up paddleboard rentals, \"NO RESERVATIONS NECESSARY\"; \"shallow and protected waters... kayak trails, 12 spoil islands, 6 miles of inland waterways, 2 state park islands\"; Caladesi Island is \"Only a 15 minute paddle from our location\". Closes in bad weather. (727) 734-0392."},{"name":"Fenway Hotel, Autograph Collection","source":"https://www.fenwayhotel.com/","accessed":"2026-10-03","si":["romance","culture","senior"],"booking_route":"own website booking engine or (844) 569-9879 (marriott.com page returned HTTP 403)","commission_status":"commissioned","commission":"hotel","tier":"premier","price_band":"premier","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"published","wells":["stay","eat"],"draw_rank":17,"blurb":"453 Edgewater Dr., Dunedin; an Autograph Collection hotel with HEW Parlor & Chophouse and the Hi-Fi Rooftop Bar, \"Originally home to WGHB in 1925\"; reservations (844) 569-9879."},{"name":"Hampton Inn Dunedin","source":"https://wanderflorida.net/accommodation-dunedin-fl/","accessed":"2026-10-03","si":["family","senior"],"booking_route":"hilton.com (brand booking; not fetched - HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":18,"blurb":"A Hilton-brand hotel \"Opened in 2019\", described as \"the only one on the Dunedin Causeway\", with free breakfast, pet-friendly rooms and included parking; guests can walk the causeway, \"rent kayaks to visit Caladesi Island\" and \"enjoy the beaches at Honeymoon Island.\" Source is a Florida travel guide, because hilton.com returned HTTP 403."},{"name":"Holiday Inn Express Hotel & Suites Clearwater North-Dunedin","source":"https://wanderflorida.net/accommodation-dunedin-fl/","accessed":"2026-10-03","si":["family","senior"],"booking_route":"ihg.com (brand booking; not fetched - HTTP 403)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","commission_basis":"benchmark","wells":["stay"],"draw_rank":19,"blurb":"An IHG hotel \"on a prime corner in downtown Dunedin, at the corner of Broadway and Skinner and backing to the popular Pinellas Trail\"; parking and breakfast included; \"Main Street is less than a half mile away.\" Source is a Florida travel guide, because ihg.com returned HTTP 403."},{"name":"Clearwater / Lake Tarpon KOA Holiday","source":"https://koa.com/campgrounds/clearwater-lake/","accessed":"2026-10-03","si":["motoring","family","glamping"],"booking_route":"koa.com online reservations or (727) 937-8412","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":20,"blurb":"37061 US Hwy 19 N, Palm Harbor: \"a resort-style RV park and campground\" \"Set between Clearwater and Tarpon Springs\", \"the closest KOA to Tampa\"; RV sites with a KOA Patio, Deluxe Cabins with full baths and Premium Tent Sites; pool, dog park, and \"a free breakfast buffet served every morning\"; \"Full Hookup RV Sites Starting at $69!\" (727) 937-8412."},{"name":"Sun Retreats Dunedin","source":"https://www.hipcamp.com/en-US/d/united-states/florida/palm-harbor/camping/glamping","accessed":"2026-10-03","si":["motoring","senior","family"],"booking_route":"Hipcamp listing; sunoutdoors.com returned HTTP 403","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":21,"blurb":"\"formerly known as Dunedin RV Resort\", \"Nestled in a tree grove near Clearwater beaches\": \"more than 230 spacious RV sites\", heated outdoor pool, shuffleboard, pet walk and fitness centre, plus the on-site Blue Moon Inn with kitchenette rooms. Hipcamp lists it \"2.1mi from Palm Harbor\"."},{"name":"Fort De Soto Park campground","source":"https://pinellas.gov/parks/fort-de-soto-park/","accessed":"2026-10-03","si":["family","wildlife","motoring"],"booking_route":"Pinellas County camping reservations (camping information page)","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":22,"blurb":"Pinellas County''s largest park: \"1,136 acres made up of five interconnected islands\" with a \"236-site family camping area with facilities\", \"almost three miles of beautiful white sandy beach\", a dog beach, the historic fort, and \"seven miles of paved trail connecting North Beach, East Beach, the boat ramp and the camping area.\" 3500 Pinellas Bayway South, Tierra Verde."},{"name":"The Olive Grove","source":"https://www.hipcamp.com/en-US/d/united-states/florida/palm-harbor/camping/glamping","accessed":"2026-10-03","si":["glamping","romance","culinary"],"booking_route":"Hipcamp","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":23,"blurb":"\"Aframe Cabin Tent nestled in a 4 acre olive orchard\" on a working farm that mills its own extra virgin olive oil; queen bed, Wi-Fi, heat and AC, TV, fire pit, separate kitchenette and hot-water bathrooms; \"No pets please\". Hipcamp lists it \"37mi from Palm Harbor\", 12 sites."},{"name":"The Funky Flamingo","source":"https://www.hipcamp.com/en-US/d/united-states/florida/palm-harbor/camping/glamping","accessed":"2026-10-03","si":["glamping","adventure","river"],"booking_route":"Hipcamp","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":24,"blurb":"Weeki Wachee, \"on the Mud Spring between the Gulf Of Mexico and Weeki Wachee River\": a camper on an Old Florida waterfront with \"500 feet of waterfront\"; \"Kayaks are provided\", vintage 1960s small-boat rentals, a grill, outdoor sink and restroom. Hipcamp lists it \"33mi from Palm Harbor\", 1 site."},{"name":"Frenchy''s Outpost Bar & Grill","source":"https://frenchysonline.com/frenchys-outpost-bar-grill/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in; online ordering on Toast","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":25,"blurb":"466 Causeway Blvd, Dunedin: \"an open-air Key West Style restaurant situated near the causeway to beautiful Honeymoon Island\", with a large tiki bar; the newest of the Frenchy''s family, \"Local favorite since 1981\". (727) 625-3619."},{"name":"Madison Avenue Pizza","source":"https://www.madisonavepizza.com/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in or online ordering; large-party reservations via the site","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":26,"blurb":"2660 Bayshore Boulevard, Dunedin, \"at the intersection of Alternate 19 and Curlew, right by Honeymoon Island\": brick-oven pizza \"homemade from scratch\", calzones, strombolis and wings; dine in or carry out; closed Tuesdays."},{"name":"Dunedin Brewery","source":"https://dunedinbrewery.com/","accessed":"2026-10-03","si":["culinary","entertainment"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":27,"blurb":"937 Douglas Avenue, Dunedin: \"FL''s Oldest Microbrewery\", \"Brewing since 1996\" - \"the oldest distributing microbrewery still in operation\" in Florida, with pub food and live music on two stages every weekend; kitchen open daily from 11am. 727-736-0606."},{"name":"The Living Room","source":"https://www.tlr.restaurant/","accessed":"2026-10-03","si":["culinary","romance"],"booking_route":"reservations via the restaurant''s site","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":28,"blurb":"487 Main Street, Dunedin: \"Eclectic Fine Dining in Tampa Bay\", with music and reservations; a sister room in Wesley Chapel; the site states a 15% service charge."},{"name":"HEW Parlor & Chophouse","source":"https://www.fenwayhotel.com/","accessed":"2026-10-03","si":["culinary","romance"],"booking_route":"hotel reservations line or 727-683-5999","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":29,"blurb":"At the Fenway Hotel, 453 Edgewater Dr., Dunedin: \"The namesake of Herman Everett Wendell. Classic, chef-driven, show stopping\"; with the Hi-Fi Rooftop Bar upstairs, \"Originally home to WGHB in 1925\"."},{"name":"Hellas Restaurant & Bakery","source":"https://hellasbakery.com/","accessed":"2026-10-03","si":["culinary","culture","family"],"booking_route":"reservations and to-go ordering via the site, or (727) 943-2400","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat","shop"],"draw_rank":30,"blurb":"785 Dodecanese Blvd, Tarpon Springs: \"our family has been serving authentic Greek food and pastries for over 50 years\", \"in the heart of the historic Sponge Docks\"; restaurant plus European-style bakery. (727) 943-2400."},{"name":"St. Nicholas Boat Line","source":"https://stnicholasboatline.com/","accessed":"2026-10-03","si":["culture","family","river"],"booking_route":"walk-up ticket booth on Dodecanese Boulevard, no reservations","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":31,"blurb":"From the Tarpon Springs Sponge Docks: \"a sponge diving demonstration cruise on the Anclote River\" where a diver suits up \"in over 170 pounds of traditional diving equipment\" and harvests a live sponge; \"Family-owned since 1924 and pet-friendly\", \"one of the oldest continuously operating attractions in the State of Florida\"; \"No reservations needed\"."},{"name":"Dunedin","source":"https://visitdunedinfl.com/places-to-stay/","accessed":"2026-10-03","si":["culture","culinary","family"],"booking_route":"none needed - a town","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":32,"blurb":"The gateway town: Florida State Parks places Honeymoon Island \"Just two miles west of Dunedin\". Visit Dunedin lists ferries, trolleys and tiki rides under getting around, and bed & breakfasts, boutique hotels and inns among its places to stay."}],"faq":[{"q":"What is the entrance fee for Honeymoon Island State Park?","a":"Florida State Parks lists \"$8 per vehicle (limit eight people)\", \"$4 single-occupant vehicle\", \"$2 pedestrians, bicyclists, extra passengers\", and a \"$4 per vehicle: Sunset fee, starting one hour prior to park closing\".","source":"https://web.archive.org/web/20251209115729/https://www.floridastateparks.org/parks-and-trails/honeymoon-island-state-park/hours-fees","accessed":"2026-10-03"},{"q":"What are Honeymoon Island State Park''s hours?","a":"\"8 a.m. to sunset, 365 days a year.\" The Rotary Centennial Nature Center inside the park is \"open 9 a.m. to 5 p.m. Wednesday through Sunday.\"","source":"https://web.archive.org/web/20260909134454/https://www.floridastateparks.org/parks-and-trails/honeymoon-island-state-park","accessed":"2026-10-03"},{"q":"Is Honeymoon Island State Park dog friendly?","a":"In designated areas: \"Dogs are allowed in designated areas such as the pet beach on the southern tip of the island and on the nature trail. Pets must be on a 6-foot hand-held leash at all times in these areas.\" Service animals are allowed in all areas.","source":"https://web.archive.org/web/20260902182917/https://www.floridastateparks.org/parks-and-trails/honeymoon-island-state-park/experiences-amenities","accessed":"2026-10-03"},{"q":"How does the Honeymoon Island State Park ferry to Caladesi Island work?","a":"\"There are two ferry boats that depart from Honeymoon Island Docks.\" The ferry \"departs hourly all year, beginning at 10am, with half hour departures Mid-February thru Labor Day and weekends\", with a \"Maximum stay of up to 4 hours\". It runs \"every day except Thanksgiving and Christmas weather permitting.\"","source":"https://caladesiferry.org/schedules-and-pricing/","accessed":"2026-10-03"},{"q":"How much does the Caladesi Island State Park ferry cost?","a":"Round trip: \"Adults $20\", \"Children (6-12) $10\", \"5 and Under Free\", with a military discount for active-duty and retired personnel. \"Tickets for the ferry must be purchased at Caladesi Ferry Ticket Office at Honeymoon Island State Park. Tickets are not available for purchase online!\"","source":"https://caladesiferry.org/schedules-and-pricing/","accessed":"2026-10-03"},{"q":"What trails are at Honeymoon Island State Park?","a":"\"Observe one of the few remaining South Florida virgin slash pine stands along the Osprey Trail, which provides visitors with 2.5 miles of walking.\" Walkers and runners also use \"the park drive, the Osprey Trail and four miles of beach\", and Wheel Fun Rentals bikes ride \"paved trails throughout the island.\"","source":"https://web.archive.org/web/20260902182917/https://www.floridastateparks.org/parks-and-trails/honeymoon-island-state-park/experiences-amenities","accessed":"2026-10-03"},{"q":"Can you swim at Honeymoon Island State Park?","a":"Yes, in \"areas designated for swimming on the main beach\". Watch the warning flags - \"Double red flags mean absolutely no swimming because of high winds and undertow currents\" - and note \"Lifeguards are not provided.\" At the north-end cut, the park says \"do not venture into or through the water.\"","source":"https://web.archive.org/web/20260902182917/https://www.floridastateparks.org/parks-and-trails/honeymoon-island-state-park/experiences-amenities","accessed":"2026-10-03"},{"q":"Can you fish at Honeymoon Island State Park?","a":"Yes: \"Surf and pass fishing can yield catches of flounder, snook, trout, redfish, snapper, whiting, sheepshead, pompano, Spanish mackerel, cobia, ladyfish and tarpon.\" Fishing must follow state rules on size, number, method and season, and \"A fishing license may be required.\"","source":"https://web.archive.org/web/20260902182917/https://www.floridastateparks.org/parks-and-trails/honeymoon-island-state-park/experiences-amenities","accessed":"2026-10-03"},{"q":"Is Honeymoon Island a state park?","a":"Yes. \"In 1974, the state of Florida purchased 113 acres of the island. Over the next six years, Florida purchased the remaining parcels of land on the island, and on Dec. 7, 1981, Honeymoon Island State Recreation Area was created.\" It is now run by Florida State Parks as Honeymoon Island State Park.","source":"https://web.archive.org/web/20260810070135/https://www.floridastateparks.org/parks-and-trails/honeymoon-island-state-park/history","accessed":"2026-10-03"},{"q":"Can you kayak to Caladesi Island State Park?","a":"Yes. Sail Honeymoon on the Dunedin Causeway rents kayaks and SUPs with \"NO RESERVATIONS NECESSARY\" and says Caladesi Island is \"Only a 15 minute paddle from our location\". On the island, Florida State Parks lists \"over 3 miles of paddling through the majestic mangrove tunnels\".","source":"https://www.sailhoneymoon.com/","accessed":"2026-10-03"}],"seo":{"meta_title":"Honeymoon Island State Park: Beaches, Osprey Trail & Caladesi Ferry | TravelWell","meta_description":"Four miles of Gulf beach, a pet beach, the 2.5-mile Osprey Trail, the Caladesi Island ferry, and where to stay, camp and eat around Dunedin.","slug":"honeymoon-island-state-park-florida","primary_keyword":"Honeymoon Island State Park","jsonld_type":"TouristDestination"},"hero":{"query":"Honeymoon Island State Park beach Dunedin"}}'::jsonb, 46)
